module.exports = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\" />\n<meta name=\"apple-mobile-web-app-title\" content=\"Image Studio\" />\n<meta name=\"theme-color\" content=\"#111114\" />\n<title>Image Studio KH — Web</title>\n<!--\n  Image Studio KH — Phase-1 web/iPad client.\n\n  A self-contained, build-free viewer that talks to the SAME server your\n  Mac clients use (HTTP+WS RPC over Tailscale). It needs no changes to the\n  app or server: it POSTs to /api/rpc and fetches /assets/<rel> with the\n  Bearer token via fetch() (which, unlike <img src>, can send the auth\n  header — so images load as blob URLs).\n\n  This is read-only on purpose: it proves the iPad → server pipeline and\n  gives a usable Library browser. The full editable app (the real React UI\n  served from the server) is phase 2.\n\n  How to run: serve this folder over http on the server Mac, e.g.\n    cd webclient && python3 -m http.server 8088\n  then on the iPad open  http://<mac-tailscale-name>:8088/  and enter your\n  server URL (e.g. http://<mac-tailscale-name>:41xx) + a user token from\n  Settings → Multi-Mac on the server.\n-->\n<style>\n  :root {\n    --bg: #f6f6f8; --surface: #fff; --text: #1a1a1f; --muted: #6a6a73;\n    --border: rgba(0,0,0,0.12); --border-strong: rgba(0,0,0,0.22);\n    --accent: #2563eb; --accent-bg: #eef2ff; --radius: 12px;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --bg: #0e0e11; --surface: #18181c; --text: #ececf0; --muted: #9a9aa3;\n      --border: rgba(255,255,255,0.12); --border-strong: rgba(255,255,255,0.24);\n      --accent: #6b9bff; --accent-bg: #1a2540;\n    }\n  }\n  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n  html, body { margin: 0; height: 100%; }\n  body {\n    font: 15px/1.45 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n    background: var(--bg); color: var(--text);\n    padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);\n  }\n  button { font: inherit; cursor: pointer; }\n  .btn {\n    border: 1px solid var(--border-strong); background: var(--surface); color: var(--text);\n    border-radius: 10px; padding: 10px 16px; font-weight: 500;\n  }\n  .btn--primary { background: var(--accent); color: #fff; border-color: var(--accent); }\n  .btn:active { opacity: 0.7; }\n  input, select {\n    font: inherit; width: 100%; padding: 12px 14px; border: 1px solid var(--border-strong);\n    border-radius: 10px; background: var(--surface); color: var(--text); -webkit-appearance: none;\n  }\n  .muted { color: var(--muted); }\n\n  /* ── Connect screen ── */\n  #connect { max-width: 460px; margin: 0 auto; padding: 40px 20px; }\n  #connect h1 { font-size: 22px; margin: 0 0 4px; }\n  #connect .sub { color: var(--muted); margin: 0 0 24px; }\n  #connect label { display: block; font-weight: 600; font-size: 13px; margin: 16px 0 6px; }\n  #connect .hint { font-size: 12px; color: var(--muted); margin-top: 6px; }\n  #connect .err { color: #e5484d; font-size: 13px; margin-top: 14px; min-height: 18px; }\n  #connect .actions { margin-top: 24px; }\n\n  /* ── App shell ── */\n  #app { display: none; max-width: 1100px; margin: 0 auto; }\n  /* v0.46.0: vertical 4-row appbar. Row 1 pairs the company chip with the\n     Disconnect icon (we're disconnecting from THIS company). Row 2 is the\n     category filter chips. Row 3 is a full-width search box. Row 4 is the\n     tiny product count, below the search where it doesn't fight for space. */\n  header.bar {\n    position: sticky; top: 0; z-index: 5; background: var(--bg);\n    display: flex; flex-direction: column; gap: 10px;\n    padding: 12px 16px; padding-top: max(12px, env(safe-area-inset-top));\n    border-bottom: 1px solid var(--border);\n  }\n  header.bar .bar-top { display: flex; align-items: center; gap: 10px; }\n  header.bar .spacer { flex: 1; }\n  header.bar .search { width: 100%; }\n  header.bar .count { font-size: 11px; color: var(--muted); padding-left: 2px; }\n  header.bar .bar-cats { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }\n\n  /* Compact round icon button — disconnect + sheet-close buttons share this. */\n  .icon-btn {\n    display: inline-flex; align-items: center; justify-content: center;\n    width: 38px; height: 38px; padding: 0;\n    border: 1px solid var(--border-strong); background: var(--surface); color: var(--text);\n    border-radius: 50%;\n  }\n  .icon-btn:active { opacity: 0.7; }\n  .icon-btn svg { width: 18px; height: 18px; display: block; }\n  /* v0.49.1: refresh button spins while a reload is in flight. */\n  .icon-btn.is-spinning svg { animation: spinSpin 0.7s linear infinite; }\n  @keyframes spinSpin { from { transform: rotate(0); } to { transform: rotate(360deg); } }\n  /* v0.49.2: small count badge on the AI activity button. Hidden when 0\n     (the `hidden` HTML attr does the work; this just styles the visible state). */\n  .icon-btn--badged { position: relative; }\n  .icon-btn--badged .badge {\n    position: absolute; top: -4px; right: -4px;\n    min-width: 18px; height: 18px; padding: 0 5px;\n    background: var(--accent); color: #fff;\n    border-radius: 999px; font-size: 11px; font-weight: 700; line-height: 18px;\n    text-align: center; box-shadow: 0 0 0 2px var(--bg);\n  }\n  /* v0.49.2: AI activity rows — small source thumb, SKU + prompt label,\n     status pill on the right. Repair button (failed only) wraps to its own\n     line so the tap target stays at 38px on phone widths. */\n  .ai-activity-row { gap: 12px; }\n  .ai-activity-row .thumb {\n    width: 44px; height: 44px; border-radius: 8px; background-size: cover;\n    background-position: center; background-color: var(--border); flex-shrink: 0;\n  }\n  .ai-activity-row .meta { flex: 1; min-width: 0; }\n  .ai-activity-row .meta strong { display: block; font-weight: 600; font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .ai-activity-row .meta .sub {\n    display: block; color: var(--muted); font-size: 12px; margin-top: 2px;\n    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  }\n  .ai-activity-row .pill {\n    flex-shrink: 0; padding: 3px 10px; border-radius: 999px;\n    font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;\n  }\n  .ai-activity-row .pill--queued  { background: rgba(100,116,139,0.16); color: #475569; }\n  .ai-activity-row .pill--running { background: rgba(37,99,235,0.16);   color: var(--accent); }\n  .ai-activity-row .pill--failed  { background: rgba(234,88,12,0.16);    color: #c2410c; }\n  .ai-activity-row .repair-line { width: 100%; display: flex; justify-content: flex-end; padding-top: 8px; }\n  .ai-activity-row .repair-line .btn { padding: 6px 12px; font-size: 13px; }\n  .ai-activity-row.is-failed { flex-wrap: wrap; }\n\n  /* Company chip — initials in a pill so the bar isn't dominated by long names. */\n  .co-btn {\n    display: inline-flex; align-items: center; gap: 6px;\n    min-width: 38px; height: 38px; padding: 0 12px;\n    border: 1px solid var(--accent); background: var(--accent-bg); color: var(--accent);\n    border-radius: 999px; font-weight: 700; font-size: 13px; letter-spacing: 0.02em;\n  }\n  .co-btn:active { opacity: 0.7; }\n  .co-btn .chev { width: 14px; height: 14px; opacity: 0.75; }\n\n  /* Filter chips (All + Category picker). Active = filled accent. */\n  .chip {\n    display: inline-flex; align-items: center; gap: 6px;\n    padding: 7px 12px; min-height: 32px;\n    border: 1px solid var(--border-strong); background: var(--surface); color: var(--text);\n    border-radius: 999px; font-weight: 500; font-size: 14px;\n  }\n  .chip:active { opacity: 0.7; }\n  .chip.is-active { background: var(--accent); color: #fff; border-color: var(--accent); }\n  .chip svg { width: 16px; height: 16px; flex-shrink: 0; }\n  .chip .chev { opacity: 0.75; }\n\n  /* v0.49.8: hint text at the top of the scope sheet — explains the action\n     in one line (\"This will overwrite the originals — there\\'s no undo.\").\n     Muted color, smaller font so it doesn\\'t dominate the row list. */\n  .scope-sheet-hint {\n    padding: 4px 16px 8px; font-size: 12px; color: var(--muted); line-height: 1.4;\n  }\n  .scope-sheet-hint.is-danger { color: #c2410c; }\n\n  /* v0.49.9: Reframe & crop sheet — preview at the top, chip rows beneath,\n     primary Apply button at the bottom. Preview area has a fixed height so\n     the chip rows below don\\'t jump as the preview re-renders.\n     v0.49.10: the inner content scrolls (overflow-y:auto) so the Apply\n     button is always reachable even when the chip rows + preview overflow.\n     `min-height:0` is the magic flex-child trick that lets a flex column\n     actually shrink its content area instead of getting clipped. */\n  .reframe-sheet {\n    padding: 4px 16px 16px; display: flex; flex-direction: column; gap: 14px;\n    overflow-y: auto; -webkit-overflow-scrolling: touch;\n    flex: 1; min-height: 0;\n    padding-bottom: max(16px, env(safe-area-inset-bottom));\n  }\n  /* v0.49.10: on tablet+ the sheet was capped at the global 560 / 70vh box,\n     which felt cramped on iPad and hid the lower chip rows behind the fold.\n     Reframe needs more room because it has a preview image + 4 control rows.\n     Caps so it still feels like a centred sheet, not a fullscreen takeover. */\n  @media (min-width: 640px) {\n    #reframeSheet .sheet-box,\n    #enhanceSheet .sheet-box,\n    #overlaySheet .sheet-box {\n      max-width: min(880px, 92vw);\n      max-height: min(92vh, 920px);\n      width: 100%;\n    }\n  }\n  /* v0.49.14: Overlay template picker — a horizontal strip of thumbnail\n     cards (template name + a tiny rendered icon). Tap to select; selected\n     gets the accent ring. Empty state when no templates exist yet. */\n  .overlay-template-strip {\n    display: flex; gap: 10px; overflow-x: auto; -webkit-overflow-scrolling: touch;\n    scrollbar-width: none; padding: 4px 2px;\n    scroll-snap-type: x proximity;\n  }\n  .overlay-template-strip::-webkit-scrollbar { display: none; }\n  .overlay-template-card {\n    flex: 0 0 130px; scroll-snap-align: start;\n    border: 1.5px solid var(--border-strong); border-radius: var(--radius);\n    background: var(--surface); padding: 10px;\n    display: flex; flex-direction: column; gap: 4px; cursor: pointer;\n  }\n  .overlay-template-card.is-active { border-color: var(--accent); background: var(--accent-bg); }\n  .overlay-template-card .name { font-weight: 600; font-size: 13px; color: var(--text); }\n  .overlay-template-card .meta { font-size: 11px; color: var(--muted); }\n  .overlay-empty { padding: 20px; text-align: center; font-size: 13px; color: var(--muted); }\n  /* v0.49.11: preview is now BIG. The 42vh cap squashed it to ~140px on a\n     phone and ~310px on iPad, so the user couldn\\'t actually evaluate the\n     result before applying. Now it\\'s width-driven (square) up to 75vh —\n     fills most of the visible viewport, controls live below the fold and\n     are reached by scrolling. `flex-shrink: 0` is critical because the\n     parent (.reframe-sheet) is a flex column with overflow-y:auto; without\n     it the flex algorithm would squish the preview back down to make room\n     for the chip rows. We WANT the chip rows to live below the fold. */\n  .reframe-preview {\n    position: relative; width: 100%; aspect-ratio: 1;\n    max-height: 75vh;\n    flex-shrink: 0;\n    background: repeating-conic-gradient(#f3f3f3 0% 25%, #ffffff 0% 50%) 0 0 / 20px 20px;\n    border: 1px solid var(--border); border-radius: var(--radius);\n    overflow: hidden; display: flex; align-items: center; justify-content: center;\n  }\n  [data-theme=\"dark\"] .reframe-preview { background: repeating-conic-gradient(#262626 0% 25%, #1e1e1e 0% 50%) 0 0 / 20px 20px; }\n  .reframe-preview img { max-width: 100%; max-height: 100%; display: block; object-fit: contain; }\n  .reframe-preview .reframe-busy {\n    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;\n    background: rgba(255,255,255,0.55); color: var(--muted); font-size: 13px;\n  }\n  [data-theme=\"dark\"] .reframe-preview .reframe-busy { background: rgba(0,0,0,0.55); }\n  .reframe-preview .reframe-busy[hidden] { display: none; }\n  .reframe-preview-label {\n    text-align: center; font-size: 12px; color: var(--muted); margin-top: -6px;\n  }\n  /* Each control row: small label on top + a chip row beneath. */\n  .reframe-row { display: flex; flex-direction: column; gap: 6px; }\n  .reframe-row-label {\n    font-size: 11px; font-weight: 700; color: var(--muted);\n    text-transform: uppercase; letter-spacing: 0.06em; padding-left: 2px;\n  }\n  .reframe-chips { display: flex; flex-wrap: wrap; gap: 8px; }\n  .reframe-chips .chip { font-size: 13px; padding: 6px 12px; min-height: 30px; }\n  /* Color swatch chip — the dot lives inside the chip beside the label. */\n  .reframe-color-swatch {\n    width: 14px; height: 14px; border-radius: 50%;\n    border: 1px solid rgba(0,0,0,0.15); box-shadow: inset 0 0 0 1px rgba(255,255,255,0.4);\n  }\n  /* Bottom action row — Cancel on the left, Apply primary on the right. */\n  .reframe-actions { display: flex; gap: 10px; padding-top: 4px; }\n  .reframe-actions .btn { flex: 1; padding: 12px; font-weight: 600; }\n\n  /* v0.49.7: direction-toggle pill at the top of the sort sheet. Bigger tap\n     target than the standard chip; the up/down icon rotates 180° on .is-desc. */\n  .sort-dir-row { padding: 8px 14px 4px; display: flex; }\n  .sort-dir-row .chip { width: 100%; justify-content: center; padding: 10px 16px; }\n  .sort-dir-row .chip svg { transition: transform 0.15s ease; }\n  .sort-dir-row .chip.is-desc svg { transform: rotate(180deg); }\n\n  /* Bottom-anchored sheet on phones, centered card on tablet+. */\n  .sheet-overlay { position: fixed; inset: 0; z-index: 30; background: rgba(0,0,0,0.5); display: none; }\n  .sheet-overlay.open { display: flex; align-items: flex-end; justify-content: center; }\n  @media (min-width: 640px) { .sheet-overlay.open { align-items: center; } }\n  .sheet-box {\n    background: var(--bg); width: 100%; max-width: 560px; max-height: 85vh;\n    display: flex; flex-direction: column;\n    border-top-left-radius: 16px; border-top-right-radius: 16px;\n    overflow: hidden;\n  }\n  @media (min-width: 640px) { .sheet-box { border-radius: 16px; max-height: 70vh; } }\n  .sheet-head {\n    display: flex; align-items: center; gap: 10px;\n    padding: 14px 16px; border-bottom: 1px solid var(--border);\n  }\n  .sheet-head h3 { margin: 0; font-size: 16px; font-weight: 700; flex: 1; }\n  .sheet-search { padding: 10px 16px; border-bottom: 1px solid var(--border); }\n  .sheet-search input { width: 100%; }\n  .sheet-list { overflow-y: auto; -webkit-overflow-scrolling: touch; flex: 1; padding-bottom: max(0px, env(safe-area-inset-bottom)); }\n  .sheet-row {\n    display: flex; align-items: center; gap: 10px;\n    padding: 12px 16px; border-bottom: 1px solid var(--border);\n    cursor: pointer; user-select: none;\n  }\n  .sheet-row:active { background: var(--accent-bg); }\n  .sheet-row.is-active { background: var(--accent-bg); color: var(--accent); font-weight: 600; }\n  .sheet-row .check { width: 18px; height: 18px; color: var(--accent); margin-left: auto; flex-shrink: 0; }\n  .sheet-empty { padding: 28px 16px; color: var(--muted); text-align: center; font-size: 14px; }\n\n  /* v0.49.5: keyboard-aware sheets. When iOS pops the keyboard, the visual\n     viewport shrinks but the sheet's max-height (in vh) doesn't — so the\n     sheet's top edge floats off-screen and the search input vanishes behind\n     the keyboard. JS toggles `is-keyboard` on the overlay and sets `--vvh`\n     to window.visualViewport.height; CSS then re-anchors the sheet to the\n     top and caps its height so the search input always stays in view. */\n  .sheet-overlay.is-keyboard.open {\n    align-items: flex-start !important;\n    padding-top: max(0px, env(safe-area-inset-top));\n  }\n  .sheet-overlay.is-keyboard.open .sheet-box {\n    max-height: var(--vvh, 70vh) !important;\n    border-top-left-radius: 0; border-top-right-radius: 0;\n    border-bottom-left-radius: 16px; border-bottom-right-radius: 16px;\n  }\n\n  /* v0.49.5: image preview lightbox. Fullscreen black backdrop, image fills\n     viewport at object-fit:contain. Prev/next buttons plus 1-finger swipe\n     to navigate. iOS long-press on the image still triggers \"Save Image\" so\n     users can pull it onto their camera roll without us shipping a button. */\n  #imgPreview { position: fixed; inset: 0; z-index: 50; display: none; background: rgba(0,0,0,0.95); }\n  #imgPreview.open { display: flex; align-items: center; justify-content: center; }\n  .img-preview-stage {\n    width: 100%; height: 100%;\n    display: flex; align-items: center; justify-content: center;\n    padding: 50px 14px;\n    touch-action: pinch-zoom; /* let iOS handle pinch natively */\n  }\n  .img-preview-stage img {\n    max-width: 100%; max-height: 100%;\n    object-fit: contain; display: block;\n    user-select: none; -webkit-user-drag: none;\n  }\n  .img-preview-close {\n    position: absolute; top: max(16px, env(safe-area-inset-top)); right: 16px; z-index: 2;\n  }\n  .img-preview-info {\n    position: absolute; bottom: max(20px, env(safe-area-inset-bottom)); left: 50%;\n    transform: translateX(-50%);\n    padding: 5px 14px; background: rgba(0,0,0,0.45); color: rgba(255,255,255,0.9);\n    border-radius: 999px; font-size: 13px; pointer-events: none;\n  }\n  .img-preview-nav {\n    position: absolute; top: 50%; transform: translateY(-50%); z-index: 2;\n    width: 48px; height: 48px; padding: 0; border-radius: 50%;\n    background: rgba(0,0,0,0.45); color: #fff;\n    border: 1px solid rgba(255,255,255,0.18);\n    display: flex; align-items: center; justify-content: center;\n    font-size: 28px; line-height: 1;\n  }\n  .img-preview-nav:active { background: rgba(0,0,0,0.7); }\n  .img-preview-nav:disabled { opacity: 0.25; }\n  .img-preview-nav-prev { left: 12px; }\n  .img-preview-nav-next { right: 12px; }\n\n  .grid {\n    display: grid; gap: 12px; padding: 16px;\n    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));\n  }\n  .card {\n    background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);\n    overflow: hidden; cursor: pointer; display: flex; flex-direction: column;\n  }\n  .card:active { transform: scale(0.98); }\n  .card .thumb {\n    aspect-ratio: 1; background: #e9e9ee center/cover no-repeat;\n    display: flex; align-items: center; justify-content: center; color: var(--muted); font-size: 12px;\n  }\n  @media (prefers-color-scheme: dark) { .card .thumb { background-color: #232329; } }\n  .card .meta { padding: 8px 10px; }\n  .card .sku { font-weight: 600; font-size: 13px; word-break: break-all; }\n  .card .name { color: var(--muted); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  .card .imgcount { color: var(--muted); font-size: 11px; margin-top: 2px; }\n\n  .pager { display: flex; align-items: center; justify-content: center; gap: 16px; padding: 8px 16px 28px; }\n  .loading, .empty { text-align: center; color: var(--muted); padding: 48px 16px; }\n\n  /* ── Detail sheet ── */\n  #detail { position: fixed; inset: 0; z-index: 20; background: rgba(0,0,0,0.45); display: none; }\n  #detail.open { display: block; }\n  #detail .sheet {\n    position: absolute; inset: 0; background: var(--bg); overflow-y: auto;\n    -webkit-overflow-scrolling: touch;\n  }\n  #detail .sheet-head {\n    position: sticky; top: 0; z-index: 1; background: var(--bg);\n    display: flex; align-items: center; gap: 12px; flex-wrap: wrap;\n    padding: 12px 16px; padding-top: max(12px, env(safe-area-inset-top));\n    border-bottom: 1px solid var(--border);\n  }\n  /* SKU takes the leftover space on a wide row and clips with an ellipsis\n     instead of wrapping — keeps the header to a clean single line on iPad. */\n  #detail .sheet-head .sku {\n    font-weight: 700; font-size: 17px;\n    flex: 1 1 auto; min-width: 0;\n    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n  }\n  /* Action buttons live in a group so they wrap as a unit, not individually,\n     when there isn't enough room. */\n  #detail .sheet-actions {\n    display: flex; gap: 8px; align-items: center; flex-shrink: 0;\n  }\n  /* Prevent button labels from breaking mid-word (was producing the\n     stacked \"Auto-/crop\" look on a narrow phone). */\n  #detail .sheet-head .btn { white-space: nowrap; }\n  /* Phone-sized viewports: drop the action group onto its own row,\n     and tighten the button chrome a touch.\n     v0.49.11: the action group is now a horizontal-scroll carousel — same\n     pattern as the gallery below. Previously it wrapped to multiple lines\n     once we had three buttons (↻ 360° / ✂︎ Reframe & crop / ＋ Add photo)\n     because \"Reframe & crop\" pushed the row over the iPhone\\'s ~390px\n     width. Carousel keeps it to exactly ONE line; any new edit actions\n     added later (Enhance, Overlay, …) just extend the scroll, no rewrap. */\n  @media (max-width: 640px) {\n    #detail .sheet-actions {\n      width: 100%;\n      flex-wrap: nowrap;\n      overflow-x: auto; -webkit-overflow-scrolling: touch;\n      scrollbar-width: none; /* Firefox */\n      scroll-snap-type: x proximity;\n      /* a hair of padding so the rightmost button\\'s shadow / focus ring\n         isn\\'t clipped by the scroller; doesn\\'t add visible space. */\n      padding: 2px 2px;\n      margin: -2px -2px;\n    }\n    #detail .sheet-actions::-webkit-scrollbar { display: none; } /* Safari, Chrome */\n    #detail .sheet-actions .btn { flex-shrink: 0; scroll-snap-align: start; }\n    #detail .sheet-head .btn { padding: 8px 12px; font-size: 14px; }\n    #detail .sheet-head { gap: 8px; }\n  }\n  /* v0.49.5: gallery is now a horizontal carousel so adding more images\n     doesn't push the page down. Snap-scrolling so a swipe lands cleanly on\n     the next tile. Each tile is a fixed width — phone shows ~1.5 cards\n     (next-card edge hints there's more to swipe to), iPad shows 3-4.\n     Tap a tile to open the lightbox; ⋯ menu is unchanged. */\n  #detail .gallery {\n    display: flex; gap: 10px; padding: 16px;\n    overflow-x: auto; -webkit-overflow-scrolling: touch;\n    scroll-snap-type: x proximity;\n    scroll-padding: 0 16px;\n    scrollbar-width: none; /* Firefox */\n  }\n  #detail .gallery::-webkit-scrollbar { display: none; } /* Safari, Chrome */\n  #detail .gallery figure {\n    position: relative; margin: 0;\n    background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);\n    overflow: hidden;\n    flex: 0 0 220px;\n    scroll-snap-align: start;\n    cursor: zoom-in;\n  }\n  /* Floating × delete button — over the top-right corner of each thumb. iOS\n     tap target: 36px circle is a comfortable thumb size; the dark backdrop\n     keeps it legible on both light + dark thumbnails. */\n  #detail .gallery .del {\n    position: absolute; top: 6px; right: 6px; z-index: 1;\n    width: 36px; height: 36px; border-radius: 50%;\n    background: rgba(0, 0, 0, 0.55); color: #fff; border: 1px solid rgba(255, 255, 255, 0.2);\n    display: flex; align-items: center; justify-content: center;\n    font-size: 20px; font-weight: 600; line-height: 1; padding: 0;\n  }\n  #detail .gallery .del:active { background: rgba(0, 0, 0, 0.75); }\n\n  /* v0.47.0: ⋯ menu button replaces the old × on each gallery tile. Opens\n     a contextual sheet (Set as main / Use with AI / Delete) — scales as more\n     per-image actions are added without crowding the tile corner with buttons. */\n  #detail .gallery .tile-menu {\n    position: absolute; top: 6px; right: 6px; z-index: 1;\n    width: 36px; height: 36px; border-radius: 50%;\n    background: rgba(0,0,0,0.55); color: #fff; border: 1px solid rgba(255,255,255,0.2);\n    display: flex; align-items: center; justify-content: center;\n    font-size: 22px; font-weight: 700; line-height: 1; padding: 0;\n  }\n  #detail .gallery .tile-menu:active { background: rgba(0,0,0,0.75); }\n\n  /* v0.49.8: ← → reorder buttons at the bottom corners of each gallery tile.\n     Same circular-pill style as the ⋯ menu, smaller (32px) so two of them\n     plus the figcaption don\\'t crowd the tile. They\\'re position:absolute so\n     they overlap the image — the image is still tappable for the preview\n     lightbox via fig.addEventListener(\\'click\\'), and stopPropagation on each\n     arrow prevents that fallback firing on a reorder tap. */\n  #detail .gallery .tile-arrow {\n    position: absolute; bottom: 38px; z-index: 1;\n    width: 32px; height: 32px; border-radius: 50%;\n    background: rgba(0,0,0,0.55); color: #fff;\n    border: 1px solid rgba(255,255,255,0.2);\n    display: flex; align-items: center; justify-content: center;\n    font-size: 18px; font-weight: 700; line-height: 1; padding: 0;\n  }\n  #detail .gallery .tile-arrow.left  { left: 6px; }\n  #detail .gallery .tile-arrow.right { right: 6px; }\n  #detail .gallery .tile-arrow:active { background: rgba(0,0,0,0.75); }\n  #detail .gallery .tile-arrow[disabled] { opacity: 0.35; }\n  /* v0.49.8: writer-only — same gating as the ⋯ menu rows. */\n  body[data-role=\"viewer\"]       #detail .gallery .tile-arrow,\n  body[data-role=\"photographer\"] #detail .gallery .tile-arrow { display: none !important; }\n\n  /* v0.49.12 — multi-select state. Long-press a tile (writer roles) to\n     enter; tiles get a coloured ring + checkmark badge; the per-tile ⋯ /\n     arrow buttons are hidden because their actions are single-image and\n     conflict with multi-select semantics. Tap behaviour swaps from \"open\n     lightbox\" to \"toggle selection.\" */\n  #detail .gallery figure { -webkit-touch-callout: none; } /* kill iOS long-press image-save sheet */\n  #detail .gallery figure.is-selected {\n    outline: 3px solid var(--accent); outline-offset: -3px;\n  }\n  #detail .gallery figure .select-badge {\n    position: absolute; top: 6px; left: 6px; z-index: 1;\n    width: 26px; height: 26px; border-radius: 50%;\n    background: rgba(0,0,0,0.55); color: #fff; border: 1.5px solid rgba(255,255,255,0.55);\n    display: none; align-items: center; justify-content: center; font-size: 14px; font-weight: 800;\n  }\n  /* Always show the badge in select mode (empty when unselected so users\n     can SEE the affordance to tap-to-select). Filled when selected. */\n  body.is-selecting #detail .gallery figure .select-badge { display: flex; }\n  #detail .gallery figure.is-selected .select-badge {\n    background: var(--accent); color: #fff; border-color: #fff;\n  }\n  /* In select mode the per-tile ⋯ + arrows are hidden — those actions are\n     single-image and would conflict with the bulk semantics. Reorder and\n     the ⋯ menu come back as soon as the user taps Done. */\n  body.is-selecting #detail .gallery .tile-menu,\n  body.is-selecting #detail .gallery .tile-arrow { display: none !important; }\n\n  /* Selection bar — sticky strip above the gallery showing count + actions.\n     Mirrors the iOS Photos pattern (count on the left, Select all / Done on\n     the right). Only visible while body.is-selecting. */\n  #selectionBar {\n    display: none;\n    position: sticky; top: 0; z-index: 2;\n    background: var(--accent-bg); color: var(--text);\n    border-bottom: 1px solid var(--border);\n    padding: 10px 16px;\n    align-items: center; gap: 12px;\n  }\n  body.is-selecting #selectionBar { display: flex; }\n  #selectionBar .count { flex: 1; font-weight: 700; font-size: 14px; color: var(--accent); }\n  #selectionBar .btn { padding: 6px 12px; font-size: 13px; min-height: 32px; }\n\n  /* v0.47.0: \"AI generated\" section in the product detail. Sits between the\n     fields and the regular gallery — collapsible so non-AI users aren't\n     distracted by it. Variants render as compact cards with Promote / Delete. */\n  #detail .ai-results { padding: 8px 16px 0; }\n  #detail .ai-results.empty { display: none; }\n  #detail .ai-results h4 {\n    margin: 4px 0 8px; font-size: 13px; font-weight: 600; color: var(--muted);\n    text-transform: uppercase; letter-spacing: 0.04em;\n    display: flex; align-items: center; gap: 8px;\n  }\n  #detail .ai-results h4 .badge {\n    background: var(--accent); color: #fff;\n    padding: 2px 8px; border-radius: 999px; font-size: 11px; letter-spacing: 0;\n  }\n  #detail .ai-results .ai-grid {\n    display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 10px;\n  }\n  #detail .ai-results figure {\n    margin: 0; position: relative; background: var(--surface);\n    border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden;\n  }\n  #detail .ai-results figure img, #detail .ai-results figure .thumb {\n    width: 100%; aspect-ratio: 1; object-fit: cover; display: block;\n  }\n  #detail .ai-results .ai-actions {\n    display: flex; gap: 6px; padding: 6px;\n  }\n  #detail .ai-results .ai-actions .btn {\n    flex: 1; padding: 6px 8px; font-size: 12px; border-radius: 8px;\n  }\n  #detail .ai-results .ai-status {\n    padding: 12px; text-align: center; font-size: 13px; color: var(--muted);\n    border: 1px dashed var(--border); border-radius: var(--radius);\n    display: flex; align-items: center; justify-content: center; gap: 8px;\n  }\n  #detail .ai-results .ai-status .dot {\n    width: 8px; height: 8px; border-radius: 50%; background: var(--accent);\n    animation: aiPulse 1.2s ease-in-out infinite;\n  }\n  @keyframes aiPulse { 0%,100% { opacity: 0.35; } 50% { opacity: 1; } }\n  /* v0.49.1: a separate \"broken task\" row (failed / stuck-done) with a\n     Repair button inline. Same layout as ai-status; warmer colour to signal\n     attention without screaming. Repair button on its own line on phones. */\n  #detail .ai-results .ai-broken {\n    border-color: #ea580c; background: #fff7ed; color: #9a3412; text-align: left;\n    flex-direction: column; align-items: stretch; gap: 8px;\n  }\n  @media (prefers-color-scheme: dark) {\n    #detail .ai-results .ai-broken { background: rgba(234, 88, 12, 0.12); color: #fdba74; border-color: rgba(234, 88, 12, 0.45); }\n  }\n  #detail .ai-results .ai-broken .ai-repair { align-self: flex-end; min-height: 38px; padding: 6px 14px; }\n\n  /* v0.47.0: AI sheet — vertically stacked picker rows + variants + Run. */\n  .ai-sheet { padding: 12px 16px 16px; display: flex; flex-direction: column; gap: 12px; overflow-y: auto; -webkit-overflow-scrolling: touch; }\n  .ai-source { display: flex; gap: 10px; align-items: center; padding: 10px; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); }\n  .ai-source-thumb { width: 56px; height: 56px; background-size: cover; background-position: center; background-color: var(--border); border-radius: 8px; flex-shrink: 0; }\n  .ai-source-meta { font-size: 13px; color: var(--muted); line-height: 1.35; min-width: 0; }\n  .ai-source-meta strong { display: block; color: var(--text); font-weight: 600; font-size: 14px; }\n  .ai-pick {\n    display: flex; align-items: center; gap: 10px; text-align: left;\n    padding: 12px 14px; background: var(--surface); color: var(--text);\n    border: 1px solid var(--border-strong); border-radius: var(--radius); font-size: 14px; min-height: 56px;\n  }\n  .ai-pick:active { opacity: 0.7; }\n  .ai-pick-label { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; margin-right: 4px; }\n  .ai-pick-value { flex: 1; min-width: 0; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .ai-pick .chev { width: 18px; height: 18px; opacity: 0.6; }\n  .ai-variants { display: flex; flex-direction: column; gap: 6px; }\n  .ai-variants-label { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; padding-left: 2px; }\n  .ai-variants-buttons { display: flex; gap: 6px; }\n  .ai-variants-buttons button {\n    flex: 1; min-height: 44px; border-radius: var(--radius);\n    border: 1px solid var(--border-strong); background: var(--surface); color: var(--text);\n    font-weight: 600; font-size: 15px;\n  }\n  .ai-variants-buttons button:active { opacity: 0.7; }\n  .ai-variants-buttons button.is-active { background: var(--accent); color: #fff; border-color: var(--accent); }\n  .ai-cost { font-size: 13px; color: var(--muted); padding: 2px 4px; }\n  /* v0.49.3: aspect chips. Wraps to multiple lines when there are 5+ options\n     (e.g. Nano Banana Edit has 7), each chip a 44pt-friendly tap target. */\n  .ai-aspect { display: flex; flex-direction: column; gap: 6px; }\n  .ai-aspect-chips { display: flex; flex-wrap: wrap; gap: 6px; }\n  .ai-aspect-chips button {\n    flex: 0 0 auto; min-height: 38px; min-width: 56px; padding: 6px 12px;\n    border-radius: var(--radius);\n    border: 1px solid var(--border-strong); background: var(--surface); color: var(--text);\n    font-weight: 600; font-size: 14px;\n  }\n  .ai-aspect-chips button:active { opacity: 0.7; }\n  .ai-aspect-chips button.is-active { background: var(--accent); color: #fff; border-color: var(--accent); }\n  .ai-cost strong { color: var(--text); }\n  .ai-run { min-height: 50px; font-size: 16px; font-weight: 600; }\n  .ai-run:disabled { opacity: 0.55; }\n  /* Prompt list items use sheet-row but show body excerpt below the label. */\n  .sheet-row .row-sub { display: block; font-size: 12px; color: var(--muted); font-weight: 400; margin-top: 2px; line-height: 1.3; max-height: 2.6em; overflow: hidden; text-overflow: ellipsis; }\n  .sheet-row.is-group-head { background: var(--surface); font-weight: 600; font-size: 11px; text-transform: uppercase; color: var(--muted); letter-spacing: 0.05em; padding: 8px 16px; cursor: default; }\n  .sheet-row.is-group-head:active { background: var(--surface); }\n  .sheet-row .row-meta { font-size: 12px; color: var(--muted); margin-left: auto; flex-shrink: 0; }\n\n  /* v0.45.0 → v0.47.0: role-based UI gating. Replaces the old × hiding with\n     the new ⋯ menu button (both delete + use-with-AI + set-as-main are writes,\n     so the menu itself is hidden for restricted roles). */\n  body[data-role=\"viewer\"] #addPhotoBtn,\n  body[data-role=\"viewer\"] #autoCropBtn,\n  body[data-role=\"viewer\"] #enhanceBtn,\n  body[data-role=\"viewer\"] #overlayBtn,\n  body[data-role=\"viewer\"] #aiActivityBtn,\n  body[data-role=\"viewer\"] #detail .ai-results .ai-actions,\n  body[data-role=\"photographer\"] #autoCropBtn,\n  body[data-role=\"photographer\"] #enhanceBtn,\n  body[data-role=\"photographer\"] #overlayBtn,\n  body[data-role=\"photographer\"] #aiActivityBtn,\n  body[data-role=\"photographer\"] #detail .ai-results .ai-actions { display: none !important; }\n  /* v0.49.6: the ⋯ menu is now visible for every role because it always\n     contains \"Save image to device\" — a pure read action everyone gets.\n     The menu's WRITE rows (Set as main, Use with AI, Delete) are gated\n     per-role inside openTileMenu(), in JS, instead of via CSS. */\n  #detail .gallery img { width: 100%; display: block; }\n  #detail .gallery figcaption { padding: 6px 10px; font-size: 12px; color: var(--muted); display: flex; justify-content: space-between; }\n  #detail .fields { padding: 0 16px 32px; }\n  #detail .fields .row { display: flex; justify-content: space-between; gap: 16px; padding: 10px 0; border-bottom: 1px solid var(--border); }\n  #detail .fields .k { color: var(--muted); }\n  #detail .fields .v { font-weight: 500; text-align: right; word-break: break-word; }\n\n  .toast {\n    position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%);\n    background: #1a1a1f; color: #fff; padding: 10px 16px; border-radius: 10px;\n    font-size: 13px; z-index: 40; opacity: 0; transition: opacity 0.2s; pointer-events: none;\n    max-width: 90%;\n  }\n  .toast.show { opacity: 1; }\n</style>\n</head>\n<body>\n\n<!-- Connect -->\n<section id=\"connect\">\n  <h1>Image Studio KH</h1>\n  <p class=\"sub\">Connect to your server to browse the library.</p>\n  <label for=\"srv\">Server URL</label>\n  <input id=\"srv\" type=\"url\" inputmode=\"url\" autocapitalize=\"off\" autocorrect=\"off\"\n         placeholder=\"http://mac-mini.tail-scale.ts.net:41xx\" />\n  <p class=\"hint\">The same address your Mac clients use (over Tailscale).</p>\n  <label for=\"tok\">Access token</label>\n  <input id=\"tok\" type=\"password\" autocapitalize=\"off\" autocorrect=\"off\" placeholder=\"paste a user token\" />\n  <p class=\"hint\">From the server: Settings → Multi-Mac → a user's token. Make a dedicated \"iPad\" user if you like.</p>\n  <div class=\"err\" id=\"connectErr\"></div>\n  <div class=\"actions\">\n    <button class=\"btn btn--primary\" id=\"connectBtn\" style=\"width:100%\">Connect</button>\n  </div>\n</section>\n\n<!-- App -->\n<div id=\"app\">\n  <header class=\"bar\">\n    <!-- Row 1: company chip + Disconnect on the same level. They're paired —\n         disconnecting drops your link to this company's catalog. -->\n    <div class=\"bar-top\">\n      <button class=\"co-btn\" id=\"companyBtn\" type=\"button\" aria-label=\"Switch company\" title=\"Switch company\" aria-haspopup=\"dialog\">\n        <span class=\"co-mark\" id=\"companyMark\">·</span>\n        <svg class=\"chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"6 9 12 15 18 9\"/></svg>\n      </button>\n      <span class=\"spacer\"></span>\n      <!-- v0.49.2: global AI activity. Opens a sheet listing every queued /\n           running / failed task across the active company so you can jump\n           back to whichever product is mid-generation, or repair a stuck one.\n           Badge surfaces the count when there's anything outstanding. -->\n      <button class=\"icon-btn icon-btn--badged\" id=\"aiActivityBtn\" type=\"button\" aria-label=\"AI activity\" title=\"AI activity — queued, running, failed\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M12 2l2.4 5.6L20 10l-5.6 2.4L12 18l-2.4-5.6L4 10l5.6-2.4z\"/>\n        </svg>\n        <span class=\"badge\" id=\"aiActivityBadge\" hidden>0</span>\n      </button>\n      <!-- v0.49.1: manual refresh. The web viewer doesn't get WebSocket pushes\n           for catalog changes (unlike the desktop), so what's on screen can\n           drift when a remote edit lands. Tap → bust the blob/list caches and\n           reload the current view (product list, or open detail sheet). -->\n      <button class=\"icon-btn\" id=\"refreshBtn\" type=\"button\" aria-label=\"Refresh\" title=\"Refresh — pull the latest from the server\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <polyline points=\"23 4 23 10 17 10\"/><polyline points=\"1 20 1 14 7 14\"/><path d=\"M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15\"/>\n        </svg>\n      </button>\n      <button class=\"icon-btn\" id=\"disconnect\" type=\"button\" aria-label=\"Disconnect\" title=\"Disconnect\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/>\n        </svg>\n      </button>\n    </div>\n    <!-- Row 2: category filter — \"All\" chip + Category picker chip (opens a\n         searchable sheet). Active state mirrors state.categoryFilter.\n         v0.49.7 — Sort picker chip lives on the same row. Sort + category are\n         conceptually independent (sort survives category change) but they\\'re\n         both list-shaping controls so they read better side-by-side. The row\n         already wraps on narrow phones if needed. -->\n    <div class=\"bar-cats\">\n      <button class=\"chip is-active\" id=\"catAllBtn\" type=\"button\" aria-pressed=\"true\">All</button>\n      <button class=\"chip\" id=\"catPickerBtn\" type=\"button\" aria-haspopup=\"dialog\" aria-label=\"Filter by category\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M3 5a2 2 0 0 1 2-2h4l2 3h8a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/>\n        </svg>\n        <span id=\"catPickerLabel\">Category</span>\n        <svg class=\"chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"6 9 12 15 18 9\"/></svg>\n      </button>\n      <button class=\"chip\" id=\"sortPickerBtn\" type=\"button\" aria-haspopup=\"dialog\" aria-label=\"Sort products\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M3 6h13M3 12h9M3 18h5\"/>\n          <path d=\"M17 14l4 4-4 4M21 18H13\"/>\n        </svg>\n        <span id=\"sortPickerLabel\">Newest</span>\n        <svg class=\"chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"6 9 12 15 18 9\"/></svg>\n      </button>\n    </div>\n    <!-- Row 3: search fills the full width edge-to-edge. -->\n    <input class=\"search\" id=\"search\" type=\"search\" placeholder=\"Search SKU / name…\" autocapitalize=\"off\" autocorrect=\"off\" autocomplete=\"off\" />\n    <!-- Row 4: tiny count, tucked under the search. -->\n    <span class=\"count\" id=\"count\"></span>\n  </header>\n  <div id=\"list\"><div class=\"loading\">Loading…</div></div>\n  <div class=\"pager\" id=\"pager\"></div>\n</div>\n\n<!-- Detail -->\n<div id=\"detail\"><div class=\"sheet\">\n  <div class=\"sheet-head\">\n    <button class=\"btn\" id=\"detailClose\">← Back</button>\n    <span class=\"sku\" id=\"detailSku\"></span>\n    <!-- Action buttons grouped so they wrap together to a second row on\n         narrow phones instead of breaking up one-by-one. -->\n    <div class=\"sheet-actions\">\n      <button class=\"btn\" id=\"spinBtn\" title=\"360° spin — drag to rotate through this product's photos\">↻ 360°</button>\n      <button class=\"btn\" id=\"autoCropBtn\" title=\"Trim background + reframe one or every image in this product\">✂︎ Reframe &amp; crop</button>\n      <button class=\"btn\" id=\"enhanceBtn\" title=\"White balance + auto levels + saturation boost\">✨ Enhance</button>\n      <button class=\"btn\" id=\"overlayBtn\" title=\"Apply an overlay template to the main image\">◫ Overlay</button>\n      <button class=\"btn btn--primary\" id=\"addPhotoBtn\">＋ Add photo</button>\n      <!-- accept=image/* with no capture → iOS shows Take Photo + Photo Library + Files -->\n      <input id=\"photoInput\" type=\"file\" accept=\"image/*\" multiple style=\"display:none\" />\n    </div>\n  </div>\n  <!-- v0.47.0: AI-generated variants live above the regular gallery so the\n       freshest output is the first thing you see after a run. Empty by\n       default and hidden via `.empty`. -->\n  <div class=\"ai-results empty\" id=\"aiResults\"></div>\n  <!-- v0.49.12: selection bar — shown via `body.is-selecting`. The\n       container is always in the DOM so the sticky position survives\n       gallery re-renders without flicker. -->\n  <div id=\"selectionBar\">\n    <span class=\"count\" id=\"selectionCount\">0 selected</span>\n    <button class=\"btn\" id=\"selectAllBtn\" type=\"button\">Select all</button>\n    <button class=\"btn btn--primary\" id=\"selectDoneBtn\" type=\"button\">Done</button>\n  </div>\n  <div class=\"gallery\" id=\"detailGallery\"></div>\n  <div class=\"fields\" id=\"detailFields\"></div>\n</div></div>\n\n<!-- 360° spin overlay -->\n<style>\n  #spin { position: fixed; inset: 0; z-index: 50; display: none; background: rgba(0,0,0,0.92); }\n  #spin.open { display: flex; align-items: center; justify-content: center; }\n  .spin-stage { width: 100%; height: 100%; touch-action: none; cursor: ew-resize; display: flex; align-items: center; justify-content: center; }\n  .spin-frame { width: 92vw; height: 80vh; background-position: center; background-repeat: no-repeat; background-size: contain; user-select: none; }\n  .spin-close { position: absolute; top: max(16px, env(safe-area-inset-top)); right: 16px; z-index: 2; }\n  .spin-hint { position: absolute; bottom: max(20px, env(safe-area-inset-bottom)); left: 50%; transform: translateX(-50%); color: rgba(255,255,255,0.85); background: rgba(0,0,0,0.4); border-radius: 999px; padding: 4px 14px; font-size: 12px; pointer-events: none; }\n</style>\n<div id=\"spin\">\n  <button class=\"btn spin-close\" id=\"spinClose\" aria-label=\"Close\">✕ Close</button>\n  <div class=\"spin-stage\" id=\"spinStage\"><div class=\"spin-frame\" id=\"spinFrame\"></div></div>\n  <div class=\"spin-hint\" id=\"spinHint\">↤ drag to rotate ↦</div>\n</div>\n\n<!-- v0.49.5: image preview lightbox. Opened by tapping a gallery tile. -->\n<div id=\"imgPreview\">\n  <button class=\"btn img-preview-close\" id=\"imgPreviewClose\" type=\"button\" aria-label=\"Close\">✕ Close</button>\n  <button class=\"img-preview-nav img-preview-nav-prev\" id=\"imgPreviewPrev\" type=\"button\" aria-label=\"Previous image\">‹</button>\n  <button class=\"img-preview-nav img-preview-nav-next\" id=\"imgPreviewNext\" type=\"button\" aria-label=\"Next image\">›</button>\n  <div class=\"img-preview-stage\" id=\"imgPreviewStage\"><img id=\"imgPreviewImg\" alt=\"\" /></div>\n  <div class=\"img-preview-info\" id=\"imgPreviewInfo\"></div>\n</div>\n\n<!-- v0.46.0: company switcher sheet (replaces the old <select id=\"companySel\">) -->\n<div class=\"sheet-overlay\" id=\"companySheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Switch company\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Switch company</h3>\n      <button class=\"icon-btn\" id=\"companySheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"sheet-list\" id=\"companySheetList\"></div>\n  </div>\n</div>\n\n<!-- v0.46.0: searchable category picker (the old <select id=\"catFilter\"> wasn't\n     searchable, and the catalog has many categories — typing now filters live). -->\n<div class=\"sheet-overlay\" id=\"catSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Filter by category\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Filter by category</h3>\n      <button class=\"icon-btn\" id=\"catSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"sheet-search\">\n      <input id=\"catSheetSearch\" type=\"search\" placeholder=\"Search categories…\" autocapitalize=\"off\" autocorrect=\"off\" autocomplete=\"off\" />\n    </div>\n    <div class=\"sheet-list\" id=\"catSheetList\"></div>\n  </div>\n</div>\n\n<!-- v0.49.8: scope picker sheet — the reusable \"Apply to: this / selected / all\"\n     prompt that every destructive image-edit action goes through. Title and\n     option rows are rebuilt on open from the caller\\'s context (action name,\n     total image count, current selection). Multi-select arrives in v0.49.9\n     so for now the rows are just \"This image\" + \"All N images\". -->\n<div class=\"sheet-overlay\" id=\"scopeSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Choose images to apply to\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3 id=\"scopeSheetTitle\">Apply to</h3>\n      <button class=\"icon-btn\" id=\"scopeSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div id=\"scopeSheetHint\" class=\"scope-sheet-hint\"></div>\n    <div class=\"sheet-list\" id=\"scopeSheetList\"></div>\n  </div>\n</div>\n\n<!-- v0.49.9: Reframe & crop sheet. Replaces the bare scope picker for this\n     action — the user gets a live preview + a small set of controls (scope,\n     tightness, fill mode, fill colour) before committing. Reuses the\n     existing `images:reframePreview` IPC for the preview render, and the\n     `images:autoCropProducts` IPC (now with `filepaths`) for the final commit. -->\n<div class=\"sheet-overlay\" id=\"reframeSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Reframe and crop\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3 id=\"reframeSheetTitle\">Reframe &amp; crop</h3>\n      <button class=\"icon-btn\" id=\"reframeSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"reframe-sheet\">\n      <div class=\"reframe-preview\" id=\"reframePreview\">\n        <img id=\"reframePreviewImg\" alt=\"Reframe preview\" hidden />\n        <div class=\"reframe-busy\" id=\"reframeBusy\">Rendering preview…</div>\n      </div>\n      <div class=\"reframe-preview-label\" id=\"reframePreviewLabel\"></div>\n\n      <div class=\"reframe-row\">\n        <div class=\"reframe-row-label\">Apply to</div>\n        <div class=\"reframe-chips\" id=\"reframeScopeChips\"></div>\n      </div>\n\n      <div class=\"reframe-row\">\n        <div class=\"reframe-row-label\">Tightness</div>\n        <div class=\"reframe-chips\" id=\"reframeTightChips\"></div>\n      </div>\n\n      <div class=\"reframe-row\">\n        <div class=\"reframe-row-label\">Background fill</div>\n        <div class=\"reframe-chips\" id=\"reframeFillChips\"></div>\n      </div>\n\n      <div class=\"reframe-row\" id=\"reframeColorRow\">\n        <div class=\"reframe-row-label\">Fill colour</div>\n        <div class=\"reframe-chips\" id=\"reframeColorChips\"></div>\n        <input id=\"reframeColorPicker\" type=\"color\" value=\"#FFFFFF\" style=\"position:absolute;left:-9999px;width:0;height:0;opacity:0\" tabindex=\"-1\" aria-hidden=\"true\" />\n      </div>\n\n      <div class=\"reframe-actions\">\n        <button class=\"btn\" id=\"reframeCancelBtn\" type=\"button\">Cancel</button>\n        <button class=\"btn btn--primary\" id=\"reframeApplyBtn\" type=\"button\">Apply</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- v0.49.13: Enhance sheet. Same shape as Reframe — preview at the top,\n     one control row (Strength: Subtle / Normal / Punchy), Apply / Cancel.\n     Reuses the existing `.reframe-*` CSS classes since the layout is\n     identical and they\\'re internal naming. -->\n<div class=\"sheet-overlay\" id=\"enhanceSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Enhance image\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Enhance</h3>\n      <button class=\"icon-btn\" id=\"enhanceSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"reframe-sheet\">\n      <div class=\"reframe-preview\" id=\"enhancePreview\">\n        <img id=\"enhancePreviewImg\" alt=\"Enhance preview\" hidden />\n        <div class=\"reframe-busy\" id=\"enhanceBusy\">Rendering preview…</div>\n      </div>\n      <div class=\"reframe-preview-label\" id=\"enhancePreviewLabel\"></div>\n\n      <div class=\"reframe-row\">\n        <div class=\"reframe-row-label\">Apply to</div>\n        <div class=\"reframe-chips\" id=\"enhanceScopeChips\"></div>\n      </div>\n\n      <div class=\"reframe-row\">\n        <div class=\"reframe-row-label\">Strength</div>\n        <div class=\"reframe-chips\" id=\"enhanceStrengthChips\"></div>\n      </div>\n\n      <div class=\"reframe-actions\">\n        <button class=\"btn\" id=\"enhanceCancelBtn\" type=\"button\">Cancel</button>\n        <button class=\"btn btn--primary\" id=\"enhanceApplyBtn\" type=\"button\">Apply</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- v0.49.14: Overlay sheet. Different shape from Reframe / Enhance:\n     Overlay produces a derived image (appended or replacing main), so no\n     scope picker — always operates on the product\\'s main image. Picker\n     row at the top to choose a template (horizontal scroll of cards),\n     destination chips below (Append / Replace main), preview in the\n     middle, Apply at the bottom. -->\n<div class=\"sheet-overlay\" id=\"overlaySheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Apply overlay\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Overlay</h3>\n      <button class=\"icon-btn\" id=\"overlaySheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"reframe-sheet\">\n      <div class=\"reframe-preview\" id=\"overlayPreview\">\n        <img id=\"overlayPreviewImg\" alt=\"Overlay preview\" hidden />\n        <div class=\"reframe-busy\" id=\"overlayBusy\">Pick a template to preview…</div>\n      </div>\n      <div class=\"reframe-preview-label\" id=\"overlayPreviewLabel\"></div>\n\n      <div class=\"reframe-row\">\n        <div class=\"reframe-row-label\">Template</div>\n        <div class=\"overlay-template-strip\" id=\"overlayTemplateStrip\"></div>\n      </div>\n\n      <div class=\"reframe-row\">\n        <div class=\"reframe-row-label\">Destination</div>\n        <div class=\"reframe-chips\" id=\"overlayDestChips\"></div>\n      </div>\n\n      <div class=\"reframe-actions\">\n        <button class=\"btn\" id=\"overlayCancelBtn\" type=\"button\">Cancel</button>\n        <button class=\"btn btn--primary\" id=\"overlayApplyBtn\" type=\"button\" disabled>Apply</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- v0.49.7: sort picker sheet. The direction toggle pill lives at the top so\n     the same screen handles \"sort by what\" + \"ascending or descending\" without\n     a second sheet. Rows below are the available sort keys (Recently edited /\n     SKU / Name / Category / Image count) — tap one to apply + close. -->\n<div class=\"sheet-overlay\" id=\"sortSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Sort products\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Sort products by</h3>\n      <button class=\"icon-btn\" id=\"sortSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <!-- Direction toggle. The label updates per sort key — \"Newest first\" /\n         \"Oldest first\" for dates, \"A → Z\" / \"Z → A\" for strings, \"High to low\"\n         / \"Low to high\" for the image-count number column. -->\n    <div class=\"sort-dir-row\">\n      <button class=\"chip is-active\" id=\"sortDirToggle\" type=\"button\" aria-label=\"Toggle sort direction\">\n        <span id=\"sortDirLabel\">Newest first</span>\n        <svg id=\"sortDirIcon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <polyline points=\"6 15 12 9 18 15\"/>\n        </svg>\n      </button>\n    </div>\n    <div class=\"sheet-list\" id=\"sortSheetList\"></div>\n  </div>\n</div>\n\n<!-- v0.47.0: per-gallery-tile action menu. Title + actions are rebuilt every\n     open from the tile's context (set-main hidden if already main, etc.) -->\n<div class=\"sheet-overlay\" id=\"tileMenuSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Image actions\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3 id=\"tileMenuTitle\">Image</h3>\n      <button class=\"icon-btn\" id=\"tileMenuClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"sheet-list\" id=\"tileMenuList\"></div>\n  </div>\n</div>\n\n<!-- v0.47.0: \"Process with AI\" — the main flow sheet. Tap-to-change rows for\n     prompt + model open their own pickers; Run queues an ai:queueTask. -->\n<div class=\"sheet-overlay\" id=\"aiSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Process with AI\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Process with AI</h3>\n      <button class=\"icon-btn\" id=\"aiSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"ai-sheet\">\n      <!-- Source thumb (visual feedback of which image is being processed) -->\n      <div class=\"ai-source\" id=\"aiSource\"><div class=\"ai-source-thumb\" id=\"aiSourceThumb\"></div><div class=\"ai-source-meta\" id=\"aiSourceMeta\"></div></div>\n      <!-- Prompt card -->\n      <button class=\"ai-pick\" id=\"aiPromptPick\" type=\"button\">\n        <span class=\"ai-pick-label\">1. Prompt</span>\n        <span class=\"ai-pick-value\" id=\"aiPromptValue\">Pick a prompt…</span>\n        <svg class=\"chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"9 18 15 12 9 6\"/></svg>\n      </button>\n      <!-- Model card -->\n      <button class=\"ai-pick\" id=\"aiModelPick\" type=\"button\">\n        <span class=\"ai-pick-label\">2. Model</span>\n        <span class=\"ai-pick-value\" id=\"aiModelValue\">Pick a model…</span>\n        <svg class=\"chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"9 18 15 12 9 6\"/></svg>\n      </button>\n      <!-- v0.49.3: aspect ratio chips. Per-model — list rebuilds when the\n           model picker changes. Defaults to the saved aspect when it's in\n           the new model's list, otherwise the model's first option. Hidden\n           until a model is picked since the list depends on it. -->\n      <div class=\"ai-aspect\" id=\"aiAspectRow\" hidden>\n        <span class=\"ai-pick-label\">3. Aspect</span>\n        <div class=\"ai-aspect-chips\" id=\"aiAspectChips\" role=\"radiogroup\" aria-label=\"Aspect ratio\"></div>\n      </div>\n      <!-- v0.49.0: variants selector removed. Mobile always generates a\n           single variant per run — fat-finger protection on a small screen,\n           and predictable per-tap cost. Users can fire another run if they\n           want a second alternative. -->\n      <div class=\"ai-cost\" id=\"aiCost\">Estimated cost: —</div>\n      <button class=\"btn btn--primary ai-run\" id=\"aiRunBtn\" type=\"button\" disabled>✨ Run AI</button>\n    </div>\n  </div>\n</div>\n\n<!-- v0.47.0: searchable prompt picker. Splits results into \"My presets\" (from\n     ai:listPrompts) and \"Library\" (the static PROMPT_LIBRARY). Tapping a\n     Library item also calls ai:createPrompt to adopt it. -->\n<div class=\"sheet-overlay\" id=\"aiPromptSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Pick a prompt\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Pick a prompt</h3>\n      <button class=\"icon-btn\" id=\"aiPromptSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"sheet-search\">\n      <input id=\"aiPromptSearch\" type=\"search\" placeholder=\"Search prompts…\" autocapitalize=\"off\" autocorrect=\"off\" autocomplete=\"off\" />\n    </div>\n    <div class=\"sheet-list\" id=\"aiPromptList\"></div>\n  </div>\n</div>\n\n<!-- v0.47.0: model picker. ~10 image-to-image models with per-output price. -->\n<div class=\"sheet-overlay\" id=\"aiModelSheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Pick a model\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>Pick a model</h3>\n      <button class=\"icon-btn\" id=\"aiModelSheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"sheet-list\" id=\"aiModelList\"></div>\n  </div>\n</div>\n\n<!-- v0.49.2: global AI activity sheet. Polls while open so it stays current\n     without needing the badge poll loop to do double duty. -->\n<div class=\"sheet-overlay\" id=\"aiActivitySheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"AI activity\">\n  <div class=\"sheet-box\">\n    <div class=\"sheet-head\">\n      <h3>AI activity</h3>\n      <button class=\"icon-btn\" id=\"aiActivitySheetClose\" type=\"button\" aria-label=\"Close\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n      </button>\n    </div>\n    <div class=\"sheet-list\" id=\"aiActivityList\"></div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n(function () {\n  'use strict';\n  var LS = {\n    url: 'iskh.web.serverUrl', tok: 'iskh.web.token',\n    // v0.49.0: remember the last-used prompt + model so the AI sheet opens\n    // ready-to-run instead of empty. localStorage = per-device defaults.\n    aiPrompt: 'iskh.web.aiPrompt', aiModelKey: 'iskh.web.aiModelKey',\n    // v0.49.3 — remember last picked aspect ratio per device.\n    aiSize: 'iskh.web.aiSize',\n    // v0.49.7 — per-device product list sort preference. Survives\n    // company / category switches; resets only if the user changes it.\n    sortKey: 'iskh.web.sortKey', sortDir: 'iskh.web.sortDir',\n    // v0.49.9 — per-device Reframe & crop defaults so the sheet opens with\n    // the user\\'s last picks pre-selected instead of resetting every time.\n    reframeTight: 'iskh.web.reframeTight', // 'snug' | 'normal' | 'loose'\n    reframeFill:  'iskh.web.reframeFill',  // 'color' | 'blur'\n    reframeColor: 'iskh.web.reframeColor', // #FFFFFF | #000000 | #EAEAEA | custom hex\n    // v0.49.13 — per-device Enhance strength preset.\n    enhanceStrength: 'iskh.web.enhanceStrength', // 'subtle' | 'normal' | 'punchy'\n    // v0.49.14 — Overlay: remember last-picked template + destination per\n    // device so the sheet opens ready-to-apply.\n    overlayTemplateId: 'iskh.web.overlayTemplateId',\n    overlayDestKind:   'iskh.web.overlayDestKind', // 'append' | 'replaceMain'\n  };\n  var baseUrl = (localStorage.getItem(LS.url) || '').replace(/\\/+$/, '');\n  var token = localStorage.getItem(LS.tok) || '';\n\n  var PAGE_SIZE = 24;\n  var state = {\n    companies: [], companyId: null,\n    categories: [], categoriesById: {}, categoryFilter: '',\n    products: [], filtered: [], page: 0, search: '',\n    // v0.49.7 — product list sort. Default \"Recently edited, newest first\"\n    // matches the desktop Library default. Persisted in localStorage so the\n    // device remembers it across reloads; survives company / category switch.\n    sortKey: (localStorage.getItem(LS.sortKey) || 'updated'),\n    sortDir: (localStorage.getItem(LS.sortDir) === 'asc' ? 'asc' : 'desc'),\n    role: '', // v0.45.0 — populated from /api/whoami; drives applyRoleGating()\n    // v0.47.0 — AI flow state. Models loaded lazily on first AI sheet open.\n    aiModels: null,                  // null until first fetch; then array\n    aiPickedSource: null,            // { productId, filepath, sku, name } — the image to process\n    aiPickedPromptBody: null,        // the prompt text to send (raw or from picked preset)\n    aiPickedPromptName: null,        // display label of the picked prompt\n    aiPickedPromptTemplateId: null,  // when picked from \"My presets\", carry through for use_count bump\n    aiPickedModel: null,             // model object from listModels\n    aiPickedSize: null,              // v0.49.3 — aspect ratio string (e.g. '1:1'); per-model list\n    aiVariants: 1,                   // 1..4\n    aiPollTimer: null,               // setInterval id when polling for a running task\n    aiTileMenuFor: null,             // { productId, filepath, index, isMain } — context for the ⋯ menu\n    // v0.49.9 — Reframe & crop sheet state. Persisted defaults are read at\n    // open time; live edits live here until the sheet closes.\n    reframe: null, // { productId, imgs, focusedIndex, lockScope, scope, tight, fill, color, previewSeq, previewUrl }\n    // v0.49.13 — Enhance sheet state. Same shape as reframe but with a\n    // single \"strength\" control (Subtle / Normal / Punchy) instead of\n    // tightness + fill + colour.\n    enhance: null, // { productId, imgs, focusedIndex, lockScope, scope, strength, previewSeq, previewUrl }\n    // v0.49.14 — Overlay sheet. Different shape: source is always the\n    // product\\'s main image (parity with desktop), output is a derived\n    // image. No scope / multi-select integration — Overlay produces new\n    // images instead of editing existing ones.\n    overlay: null, // { productId, templates: [], templateId, destKind, previewSeq, previewUrl }\n    // v0.49.12 — multi-select inside one product\\'s gallery. Long-press a\n    // tile to enter; tap any tile in select-mode to toggle. Selection is\n    // a Set of `filepath` strings (not indexes) so it survives reorders.\n    // Scope = THIS product\\'s detail view; cleared on detail close + product change.\n    selectMode: false,\n    selected: new Set(),\n    suppressNextClick: false, // set after long-press fires so the click event doesn\\'t toggle\n  };\n\n  // v0.47.0: built-in prompt library mirrored from renderer/lib/promptLibrary.js\n  // so first-time mobile users have curated prompts to start from. Tapping one\n  // in the picker \"adopts\" it via ai:createPrompt so it shows in My presets too.\n  var PROMPT_LIBRARY = [\n    { id:'lib.handheld-to-studio', category:'Studio conversion', label:'Hand-taken → studio',\n      body:'Turn this casual phone photo of the product into a clean professional studio product shot on a seamless pure-white background. Even soft lighting, true-to-life colours, crisp focus, product centered and upright. Keep the product exactly as-is — do not change its shape, pattern, or proportions.' },\n    { id:'lib.catalog-white', category:'Studio conversion', label:'Catalog white background',\n      body:'Place the product on a pure white (#FFFFFF) seamless studio background. Remove all background clutter, soft even lighting, a subtle natural contact shadow beneath the product. Preserve the product’s true colours and surface texture.' },\n    { id:'lib.ecommerce-hero', category:'Studio conversion', label:'E-commerce hero shot',\n      body:'Professional e-commerce hero shot of the product: centered on a clean white background, crisp edges, gentle soft reflection beneath, bright and inviting. Magazine-quality, no props, no text.' },\n    { id:'lib.soft-studio-light', category:'Lighting', label:'Soft studio lighting',\n      body:'Relight the product with soft, diffused studio lighting coming from the upper-left, gentle falloff and no harsh shadows. Preserve the material texture and true colours; keep the background unchanged.' },\n    { id:'lib.warm-showroom', category:'Lighting', label:'Warm showroom glow',\n      body:'Relight with a warm, inviting showroom glow: soft golden key light with subtle ambient fill, premium boutique feel. Keep the product’s real colours accurate and avoid an orange colour cast.' },\n    { id:'lib.bright-even', category:'Lighting', label:'Bright & even (shadowless)',\n      body:'Relight with bright, shadowless, perfectly even lighting as used for top-down flat-lay photography. Neutral white balance, clean highlights, no blown-out areas.' },\n    { id:'lib.marble', category:'Backgrounds', label:'White marble surface',\n      body:'Place the product on a polished white marble surface with a soft neutral out-of-focus background. Natural soft lighting, premium feel, realistic contact shadow.' },\n    { id:'lib.wood-table', category:'Backgrounds', label:'Light wooden table',\n      body:'Stage the product on a light natural wooden table with a blurred neutral interior in the background. Soft daylight from a window, warm but accurate colours, shallow depth of field.' },\n    { id:'lib.gradient-backdrop', category:'Backgrounds', label:'Gradient studio backdrop',\n      body:'Place the product on a smooth studio backdrop that fades from light grey at the top to white at the bottom. Product centered, soft shadow grounding it, clean and modern.' },\n    { id:'lib.lifestyle-scene', category:'Backgrounds', label:'Lifestyle interior scene',\n      body:'Stage this {category} naturally in a tasteful modern interior setting that suits it, with soft natural light and a shallow depth of field. Keep the product the clear focus and unchanged.' },\n    { id:'lib.cutout-white', category:'Cleanup & retouch', label:'Remove background → white',\n      body:'Cleanly cut the product out from its current background and place it on a pure white background. Keep the edges crisp and natural, no haloing, preserve fine detail and true colour.' },\n    { id:'lib.remove-glare', category:'Cleanup & retouch', label:'Remove glare & reflections',\n      body:'Reduce harsh glare, hotspots, and unwanted reflections on the product surface while keeping its real colours, glaze, and texture intact. Do not flatten or repaint the material.' },\n    { id:'lib.remove-dust', category:'Cleanup & retouch', label:'Remove dust, scratches & smudges',\n      body:'Retouch out dust, fingerprints, smudges, and minor scratches from the product and background. Keep the product authentic and unmodified in shape and pattern.' },\n    { id:'lib.remove-tags', category:'Cleanup & retouch', label:'Remove price tags / stickers',\n      body:'Remove any price tags, stickers, barcodes, or stray labels from the product and reconstruct the underlying surface naturally and seamlessly.' },\n    { id:'lib.color-correct', category:'Colour', label:'True-to-life colour correct',\n      body:'Correct the white balance and exposure to neutral and render the product’s real-life colours accurately. The {color} finish should look true to life. No oversaturation, no colour cast.' },\n    { id:'lib.vivid', category:'Colour', label:'Vivid & punchy',\n      body:'Increase contrast and saturation slightly for a vivid, eye-catching catalog look while keeping skin/material tones natural and believable. Do not clip highlights or shadows.' },\n    { id:'lib.spec-sheet', category:'Product spec', label:'Product spec view',\n      body:'Produce a clean straight-on documentation view of the product suitable for a spec sheet: neutral seamless background, no props, accurate proportions and colour, evenly lit, sharp detail across the whole product.' },\n    { id:'lib.outline', category:'Product spec', label:'Outline on white',\n      body:'Render the product as a clean, sharply-defined silhouette-style shot perfectly centered on pure white, with crisp true-to-shape edges and accurate proportions. Useful as a reference / outline image.' },\n    { id:'lib.three-quarter', category:'Angles', label:'Three-quarter angle',\n      body:'Re-render the product at a flattering three-quarter angle showing the front and one side, on a clean white studio background with soft lighting and a subtle shadow. Keep the product identical in design.' },\n    { id:'lib.flat-lay', category:'Angles', label:'Top-down flat lay',\n      body:'Top-down flat-lay of the {name}, perfectly centered on a clean white surface, bright even lighting, a slight soft shadow for grounding. No props, no text.' },\n  ];\n  var blobCache = {};      // relpath -> objectURL (so we don't refetch bytes)\n  var imgListCache = {};   // productId -> images[]  (avoid refetching per product)\n  var mainImgCache = {};   // productId -> main image relpath | null\n  var thumbObserver = null; // IntersectionObserver: load thumbs only when scrolled into view\n  var currentDetail = null; // product whose detail sheet is open (for Add photo)\n\n  /* ── transport ─────────────────────────────────────────────── */\n  function rpc(channel, args) {\n    return fetch(baseUrl + '/api/rpc', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },\n      body: JSON.stringify({ channel: channel, args: args === undefined ? null : args }),\n    }).then(function (res) {\n      if (!res.ok) {\n        return res.json().catch(function () { return {}; }).then(function (j) {\n          throw new Error(j.error || (res.status === 401 ? 'Token rejected' : 'HTTP ' + res.status));\n        });\n      }\n      return res.json().then(function (b) { return b.result; });\n    });\n  }\n\n  // Fetch an asset's bytes with the Bearer header → blob URL. Server route\n  // is GET /assets/<rel> where <rel> is the image's stored relative path.\n  function assetUrl(relpath) {\n    if (!relpath) return Promise.resolve(null);\n    if (blobCache[relpath]) return Promise.resolve(blobCache[relpath]);\n    var enc = relpath.split('/').map(encodeURIComponent).join('/');\n    return fetch(baseUrl + '/assets/' + enc, { headers: { Authorization: 'Bearer ' + token } })\n      .then(function (res) { return res.ok ? res.blob() : null; })\n      .then(function (blob) {\n        if (!blob) return null;\n        var url = URL.createObjectURL(blob);\n        blobCache[relpath] = url;\n        return url;\n      })\n      .catch(function () { return null; });\n  }\n\n  function toast(msg) {\n    var t = document.getElementById('toast');\n    t.textContent = msg; t.classList.add('show');\n    clearTimeout(toast._t); toast._t = setTimeout(function () { t.classList.remove('show'); }, 2600);\n  }\n\n  /* ── connect ───────────────────────────────────────────────── */\n  function showConnect(err) {\n    document.getElementById('app').style.display = 'none';\n    document.getElementById('connect').style.display = 'block';\n    // When this page is served BY the app server (…:13180/m), the API is\n    // the same origin — prefill it so the user only needs to paste a token.\n    var prefill = baseUrl || (/^https?:/.test(location.origin || '') ? location.origin : '');\n    document.getElementById('srv').value = prefill;\n    document.getElementById('tok').value = token;\n    document.getElementById('connectErr').textContent = err || '';\n  }\n\n  document.getElementById('connectBtn').addEventListener('click', function () {\n    var u = document.getElementById('srv').value.trim().replace(/\\/+$/, '');\n    // Be forgiving: if the user omitted the scheme, assume http://.\n    if (u && !/^https?:\\/\\//i.test(u)) u = 'http://' + u;\n    var t = document.getElementById('tok').value.trim();\n    if (!u || !t) { document.getElementById('connectErr').textContent = 'Enter both the server URL and a token.'; return; }\n    this.disabled = true; this.textContent = 'Connecting…';\n    var btn = this;\n    // Validate via /api/whoami (token-checked) before saving.\n    fetch(u + '/api/whoami', { headers: { Authorization: 'Bearer ' + t } })\n      .then(function (res) {\n        if (res.status === 401) throw new Error('Token rejected by the server.');\n        if (!res.ok) throw new Error('Server reachable but returned HTTP ' + res.status + '.');\n        return res.json();\n      })\n      .then(function (whoami) {\n        baseUrl = u; token = t;\n        localStorage.setItem(LS.url, u); localStorage.setItem(LS.tok, t);\n        // Capture role so we can hide buttons that the server would 403 on\n        // anyway — server is the authoritative gate (main/util/permissions.js).\n        state.role = (whoami && whoami.user && whoami.user.role) || '';\n        applyRoleGating();\n        document.getElementById('connect').style.display = 'none';\n        document.getElementById('app').style.display = 'block';\n        boot();\n      })\n      .catch(function (e) {\n        document.getElementById('connectErr').textContent = e.message || 'Could not connect.';\n      })\n      .finally(function () { btn.disabled = false; btn.textContent = 'Connect'; });\n  });\n\n  document.getElementById('disconnect').addEventListener('click', function () {\n    if (!window.confirm('Disconnect from the server?\\n\\nYou’ll need to paste your access token again to reconnect.')) return;\n    localStorage.removeItem(LS.tok);\n    token = '';\n    showConnect('');\n  });\n\n  // v0.45.0: hide write-only controls when the connected user is a Viewer\n  // or Photographer. Server is authoritative (sends 403 on disallowed RPCs);\n  // this is purely the UX layer so the buttons don't even appear.\n  function applyRoleGating() {\n    document.body.dataset.role = state.role || '';\n  }\n\n  /* ── boot: whoami (role) → companies → products ─────────────── */\n  function boot() {\n    // On a returning session (page reload while a token's already saved)\n    // we never re-ran the Connect handler, so state.role is empty. Fetch\n    // whoami once before everything else so role-gating is set up by the\n    // time anything renders.\n    var ensureRole = state.role\n      ? Promise.resolve()\n      : fetch(baseUrl + '/api/whoami', { headers: { Authorization: 'Bearer ' + token } })\n          .then(function (res) { return res.ok ? res.json() : null; })\n          .then(function (j) { state.role = (j && j.user && j.user.role) || ''; applyRoleGating(); })\n          .catch(function () { /* non-fatal — UI just shows everything */ });\n\n    ensureRole.then(function () {\n    Promise.all([rpc('companies:list'), rpc('companies:getActiveId').catch(function () { return null; })])\n      .then(function (r) {\n        state.companies = r[0] || [];\n        var active = r[1];\n        state.companyId = (state.companies.find(function (c) { return c.id === active; }) || state.companies[0] || {}).id || null;\n        updateCompanyButton();   // v0.46.0: paints the initials chip\n        renderCompanySheet();    // v0.46.0: builds the company switcher list\n        updateSortChip();        // v0.49.7: paint the sort chip from persisted prefs\n        setActiveCompany(state.companyId);\n        loadCategories();\n        loadProducts();\n        refreshAiBadge(); // v0.49.2 — paint the AI badge on boot\n      })\n      .catch(function (e) { showConnect('Connected, but loading failed: ' + e.message); });\n    });  // ensureRole.then\n  }\n\n  // Writes (importing a photo) target the caller's ACTIVE company on the\n  // server, so keep it synced with whatever company you're viewing.\n  // Per-user (v0.15.2), so this doesn't disturb other clients.\n  function setActiveCompany(id) {\n    if (id) rpc('companies:setActive', id).catch(function () {});\n  }\n\n  document.getElementById('search').addEventListener('input', function () {\n    state.search = this.value.trim().toLowerCase(); state.page = 0; applyFilter(); render();\n  });\n\n  /* ── v0.46.0: company chip + sheet ──────────────────────────── */\n  // Paint the chip: company initial(s). Up to two letters from the first\n  // and second word, falling back to the first letter when there's only one.\n  function companyInitials(name) {\n    var parts = String(name || '').trim().split(/\\s+/).filter(Boolean);\n    if (parts.length === 0) return '·';\n    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();\n    return (parts[0][0] + parts[1][0]).toUpperCase();\n  }\n  function updateCompanyButton() {\n    var co = state.companies.find(function (c) { return c.id === state.companyId; });\n    var mark = co ? companyInitials(co.name || co.id) : '·';\n    var btn = document.getElementById('companyBtn');\n    document.getElementById('companyMark').textContent = mark;\n    btn.setAttribute('title', co ? ('Company: ' + (co.name || co.id) + ' — tap to switch') : 'Switch company');\n  }\n  function renderCompanySheet() {\n    var list = document.getElementById('companySheetList');\n    list.innerHTML = '';\n    if (!state.companies.length) {\n      list.innerHTML = '<div class=\"sheet-empty\">No companies on this server.</div>';\n      return;\n    }\n    state.companies.forEach(function (c) {\n      var row = document.createElement('div');\n      row.className = 'sheet-row' + (c.id === state.companyId ? ' is-active' : '');\n      row.innerHTML = '<span>' + escapeHtml(c.name || c.id) + '</span>'\n        + (c.id === state.companyId\n          ? '<svg class=\"check\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"20 6 9 17 4 12\"/></svg>'\n          : '');\n      row.addEventListener('click', function () { pickCompany(c.id); });\n      list.appendChild(row);\n    });\n  }\n  function pickCompany(id) {\n    if (!id || id === state.companyId) { closeSheet('companySheet'); return; }\n    state.companyId = id; state.page = 0;\n    state.categoryFilter = ''; // categories belong to the OLD company; reset.\n    updateCompanyButton();\n    setActiveCompany(id);\n    closeSheet('companySheet');\n    loadCategories();\n    loadProducts();\n  }\n  document.getElementById('companyBtn').addEventListener('click', function () {\n    renderCompanySheet();\n    openSheet('companySheet');\n  });\n\n  /* ── v0.46.0: category chips + searchable picker sheet ─────── */\n  // \"All\" chip is active when there's no category filter; the picker chip is\n  // active when there IS one, and shows the active category's name.\n  function updateCategoryButtons() {\n    var has = !!state.categoryFilter;\n    var allBtn = document.getElementById('catAllBtn');\n    var pickBtn = document.getElementById('catPickerBtn');\n    var label = document.getElementById('catPickerLabel');\n    allBtn.classList.toggle('is-active', !has);\n    allBtn.setAttribute('aria-pressed', String(!has));\n    pickBtn.classList.toggle('is-active', has);\n    label.textContent = has ? (state.categoriesById[state.categoryFilter] || 'Category') : 'Category';\n  }\n  // Build the (optionally search-filtered) list of category rows. Empty\n  // query renders the whole list; otherwise case-insensitive substring match.\n  function renderCategorySheet(query) {\n    var list = document.getElementById('catSheetList');\n    list.innerHTML = '';\n    var q = (query || '').trim().toLowerCase();\n    if (!state.categories.length) {\n      list.innerHTML = '<div class=\"sheet-empty\">No categories for this company.</div>';\n      return;\n    }\n    var matches = q\n      ? state.categories.filter(function (c) { return (c.name || '').toLowerCase().indexOf(q) !== -1; })\n      : state.categories.slice();\n    if (matches.length === 0) {\n      list.innerHTML = '<div class=\"sheet-empty\">No categories match “' + escapeHtml(query) + '”.</div>';\n      return;\n    }\n    matches.forEach(function (c) {\n      var row = document.createElement('div');\n      var active = c.id === state.categoryFilter;\n      row.className = 'sheet-row' + (active ? ' is-active' : '');\n      row.innerHTML = '<span>' + escapeHtml(c.name || c.id) + '</span>'\n        + (active\n          ? '<svg class=\"check\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"20 6 9 17 4 12\"/></svg>'\n          : '');\n      row.addEventListener('click', function () { pickCategory(c.id); });\n      list.appendChild(row);\n    });\n  }\n  function pickCategory(id) {\n    state.categoryFilter = id || '';\n    state.page = 0;\n    updateCategoryButtons();\n    applyFilter();\n    render();\n    closeSheet('catSheet');\n  }\n  document.getElementById('catAllBtn').addEventListener('click', function () { pickCategory(''); });\n  document.getElementById('catPickerBtn').addEventListener('click', function () {\n    document.getElementById('catSheetSearch').value = '';\n    renderCategorySheet('');\n    openSheet('catSheet');\n    // Defer the focus a tick so iOS Safari doesn't fight the sheet animation.\n    setTimeout(function () { document.getElementById('catSheetSearch').focus(); }, 80);\n  });\n  document.getElementById('catSheetSearch').addEventListener('input', function () {\n    renderCategorySheet(this.value);\n  });\n\n  /* ── v0.49.7: sort picker ─────────────────────────────────────\n     Mirrors the desktop Library\\'s sort vocabulary (sku / name / category /\n     images / updated). Skips brand because the mobile viewer doesn\\'t load\n     brands and would sort by raw brand IDs. Skips color/finish because it\\'s\n     rarely useful on a small screen.\n     Direction labels adapt per key — \"Newest first\" vs \"A → Z\" vs \"High to\n     low\" — because \"Ascending\" / \"Descending\" reads as jargon to staff. */\n  var SORT_OPTIONS = [\n    { key: 'updated',  label: 'Recently edited', type: 'date' },\n    { key: 'sku',      label: 'SKU',             type: 'string' },\n    { key: 'name',     label: 'Name',            type: 'string' },\n    { key: 'category', label: 'Category',        type: 'string' },\n    { key: 'images',   label: 'Image count',     type: 'number' },\n  ];\n  function sortOption(key) {\n    for (var i = 0; i < SORT_OPTIONS.length; i++) if (SORT_OPTIONS[i].key === key) return SORT_OPTIONS[i];\n    return SORT_OPTIONS[0];\n  }\n  // Direction-label vocabulary: dates read as \"Newest/Oldest\", numbers as\n  // \"High to low\", strings as \"A → Z\". Falls back if anything is off.\n  function dirLabel(opt, dir) {\n    if (opt.type === 'date')   return dir === 'desc' ? 'Newest first'    : 'Oldest first';\n    if (opt.type === 'number') return dir === 'desc' ? 'High to low'     : 'Low to high';\n    return dir === 'desc' ? 'Z → A' : 'A → Z';\n  }\n  // Pull the comparable value for one product on the active sort key.\n  // Category resolves through state.categoriesById so the user sees rows\n  // grouped under the human-readable category name, not its UUID.\n  function sortValue(p, key) {\n    if (key === 'sku')      return (p.sku || '').toLowerCase();\n    if (key === 'name')     return (p.name || '').toLowerCase();\n    if (key === 'category') return (state.categoriesById[p.categoryId] || '').toLowerCase();\n    if (key === 'images')   return Number(p.imageCount || 0);\n    /* updated */           return Number(p.updatedAt || 0);\n  }\n  // Stable sort: ties break on SKU so the order doesn\\'t jitter between\n  // renders. Numeric comparison for numbers; localeCompare with numeric:true\n  // for strings so \"AV-M81\" / \"AV-M8101\" / \"AV-M8200\" read in human order.\n  function sortProducts(items) {\n    var key = state.sortKey;\n    var dir = state.sortDir === 'asc' ? 1 : -1;\n    var type = sortOption(key).type;\n    return items.slice().sort(function (a, b) {\n      var av = sortValue(a, key), bv = sortValue(b, key);\n      var cmp;\n      if (type === 'number' || type === 'date') {\n        cmp = (av - bv);\n      } else {\n        cmp = String(av).localeCompare(String(bv), undefined, { numeric: true, sensitivity: 'base' });\n      }\n      if (cmp !== 0) return cmp * dir;\n      // Tiebreaker: SKU ascending, so equal rows have a stable order.\n      return String(a.sku || '').localeCompare(String(b.sku || ''), undefined, { numeric: true, sensitivity: 'base' });\n    });\n  }\n  // The chip label is just the option name (\"SKU\", \"Category\", …). The\n  // direction arrow lives in the chip via a tiny ▴/▾ glyph appended to the\n  // text so users see at a glance which way it\\'s sorted without opening the sheet.\n  function updateSortChip() {\n    var opt = sortOption(state.sortKey);\n    var arrow = state.sortDir === 'desc' ? ' ↓' : ' ↑';\n    document.getElementById('sortPickerLabel').textContent = opt.label + arrow;\n  }\n  function renderSortSheet() {\n    var list = document.getElementById('sortSheetList');\n    list.innerHTML = '';\n    SORT_OPTIONS.forEach(function (opt) {\n      var row = document.createElement('div');\n      var active = opt.key === state.sortKey;\n      row.className = 'sheet-row' + (active ? ' is-active' : '');\n      row.innerHTML = '<span>' + escapeHtml(opt.label) + '</span>'\n        + (active\n          ? '<svg class=\"check\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"20 6 9 17 4 12\"/></svg>'\n          : '');\n      row.addEventListener('click', function () { pickSort(opt.key); });\n      list.appendChild(row);\n    });\n    // Sync the direction toggle to the current key (label vocabulary depends\n    // on the key\\'s type — date vs string vs number).\n    var opt = sortOption(state.sortKey);\n    var btn = document.getElementById('sortDirToggle');\n    btn.classList.toggle('is-desc', state.sortDir === 'desc');\n    document.getElementById('sortDirLabel').textContent = dirLabel(opt, state.sortDir);\n  }\n  function pickSort(key) {\n    if (state.sortKey !== key) {\n      state.sortKey = key;\n      try { localStorage.setItem(LS.sortKey, key); } catch (_) {}\n    }\n    state.page = 0;\n    updateSortChip();\n    applyFilter();\n    render();\n    closeSheet('sortSheet');\n  }\n  function toggleSortDir() {\n    state.sortDir = state.sortDir === 'desc' ? 'asc' : 'desc';\n    try { localStorage.setItem(LS.sortDir, state.sortDir); } catch (_) {}\n    state.page = 0;\n    updateSortChip();\n    // Refresh the toggle\\'s label + arrow without closing the sheet — the\n    // user might want to flip the direction and then pick a different key.\n    var opt = sortOption(state.sortKey);\n    document.getElementById('sortDirToggle').classList.toggle('is-desc', state.sortDir === 'desc');\n    document.getElementById('sortDirLabel').textContent = dirLabel(opt, state.sortDir);\n    applyFilter();\n    render();\n  }\n  document.getElementById('sortPickerBtn').addEventListener('click', function () {\n    renderSortSheet();\n    openSheet('sortSheet');\n  });\n  document.getElementById('sortDirToggle').addEventListener('click', toggleSortDir);\n  document.getElementById('sortSheetClose').addEventListener('click', function () { closeSheet('sortSheet'); });\n  document.getElementById('sortSheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('sortSheet'); });\n\n  /* ── shared sheet open/close ───────────────────────────────── */\n  function openSheet(id) { document.getElementById(id).classList.add('open'); document.body.style.overflow = 'hidden'; }\n  function closeSheet(id) {\n    document.getElementById(id).classList.remove('open');\n    // Don't unlock body scroll if the product detail sheet is still open.\n    document.body.style.overflow = document.getElementById('detail').classList.contains('open') ? 'hidden' : '';\n  }\n  document.getElementById('companySheetClose').addEventListener('click', function () { closeSheet('companySheet'); });\n  document.getElementById('companySheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('companySheet'); });\n  document.getElementById('catSheetClose').addEventListener('click', function () { closeSheet('catSheet'); });\n  document.getElementById('catSheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('catSheet'); });\n\n  // Categories are per-company. Reloaded on boot and on every company switch\n  // so the picker sheet + the detail-sheet \"Category\" line stay accurate.\n  function loadCategories() {\n    if (!state.companyId) {\n      state.categories = []; state.categoriesById = {};\n      updateCategoryButtons();\n      return Promise.resolve();\n    }\n    return rpc('categories:list', state.companyId)\n      .then(function (rows) {\n        state.categories = rows || [];\n        state.categoriesById = {};\n        state.categories.forEach(function (c) { state.categoriesById[c.id] = c.name || c.id; });\n        if (state.categoryFilter && !state.categoriesById[state.categoryFilter]) state.categoryFilter = '';\n        updateCategoryButtons();\n      })\n      .catch(function () { /* non-fatal — filter just stays at \"All\" */ });\n  }\n\n  function loadProducts() {\n    document.getElementById('list').innerHTML = '<div class=\"loading\">Loading…</div>';\n    if (!state.companyId) { state.products = []; applyFilter(); render(); return; }\n    rpc('products:list', { companyId: state.companyId, filters: {} })\n      .then(function (rows) { state.products = rows || []; applyFilter(); render(); })\n      .catch(function (e) { document.getElementById('list').innerHTML = '<div class=\"empty\">' + escapeHtml(e.message) + '</div>'; });\n  }\n\n  function applyFilter() {\n    var q = state.search;\n    var cat = state.categoryFilter;\n    var filtered = state.products.filter(function (p) {\n      if (cat && p.categoryId !== cat) return false;\n      if (q && (p.sku || '').toLowerCase().indexOf(q) === -1\n            && (p.name || '').toLowerCase().indexOf(q) === -1) return false;\n      return true;\n    });\n    // v0.49.7 — sort after filter so the active sort applies INSIDE the\n    // chosen category too (user\\'s explicit ask).\n    state.filtered = sortProducts(filtered);\n  }\n\n  /* ── render grid ───────────────────────────────────────────── */\n  function render() {\n    var total = state.filtered.length;\n    var pages = Math.max(1, Math.ceil(total / PAGE_SIZE));\n    if (state.page >= pages) state.page = pages - 1;\n    var start = state.page * PAGE_SIZE;\n    var pageItems = state.filtered.slice(start, start + PAGE_SIZE);\n\n    document.getElementById('count').textContent = total + (total === 1 ? ' product' : ' products');\n\n    var list = document.getElementById('list');\n    if (total === 0) { list.innerHTML = '<div class=\"empty\">No products' + (state.search ? ' match “' + escapeHtml(state.search) + '”.' : '.') + '</div>'; }\n    else {\n      var grid = document.createElement('div'); grid.className = 'grid';\n      pageItems.forEach(function (p) { grid.appendChild(card(p)); });\n      list.innerHTML = ''; list.appendChild(grid);\n      observeThumbs(pageItems);\n    }\n\n    var pager = document.getElementById('pager');\n    pager.innerHTML = '';\n    if (pages > 1) {\n      pager.appendChild(pagerBtn('‹ Prev', state.page > 0, function () { state.page--; render(); window.scrollTo(0, 0); }));\n      var lbl = document.createElement('span'); lbl.className = 'count'; lbl.textContent = 'Page ' + (state.page + 1) + ' / ' + pages;\n      pager.appendChild(lbl);\n      pager.appendChild(pagerBtn('Next ›', state.page < pages - 1, function () { state.page++; render(); window.scrollTo(0, 0); }));\n    }\n  }\n\n  function pagerBtn(text, enabled, fn) {\n    var b = document.createElement('button'); b.className = 'btn'; b.textContent = text;\n    b.disabled = !enabled; if (enabled) b.addEventListener('click', fn);\n    return b;\n  }\n\n  function card(p) {\n    var el = document.createElement('div'); el.className = 'card'; el.dataset.id = p.id;\n    var cnt = (p.imageCount != null ? p.imageCount : '');\n    el.innerHTML =\n      '<div class=\"thumb\" data-thumb=\"' + p.id + '\">' + (cnt ? '' : 'no image') + '</div>' +\n      '<div class=\"meta\">' +\n        '<div class=\"sku\">' + escapeHtml(p.sku || '(no SKU)') + '</div>' +\n        (p.name ? '<div class=\"name\">' + escapeHtml(p.name) + '</div>' : '') +\n        (cnt !== '' ? '<div class=\"imgcount\">' + cnt + ' image' + (cnt === 1 ? '' : 's') + '</div>' : '') +\n      '</div>';\n    el.addEventListener('click', function () { openDetail(p); });\n    return el;\n  }\n\n  // Only fetch a card's thumbnail once it scrolls into view — so a page of\n  // 24 cards doesn't fire 24 full-image downloads at once (the big drag on\n  // a high-latency/remote link). Falls back to eager load if the browser\n  // lacks IntersectionObserver.\n  function observeThumbs(items) {\n    if (thumbObserver) { thumbObserver.disconnect(); thumbObserver = null; }\n    var byId = {};\n    items.forEach(function (p) { byId[p.id] = p; });\n    if (!('IntersectionObserver' in window)) { items.forEach(lazyThumb); return; }\n    thumbObserver = new IntersectionObserver(function (entries) {\n      entries.forEach(function (en) {\n        if (!en.isIntersecting) return;\n        thumbObserver.unobserve(en.target);\n        var p = byId[en.target.getAttribute('data-thumb')];\n        if (p) lazyThumb(p);\n      });\n    }, { rootMargin: '300px' }); // start loading a bit before they appear\n    document.querySelectorAll('.thumb[data-thumb]').forEach(function (el) { thumbObserver.observe(el); });\n  }\n\n  function lazyThumb(p) {\n    if (p.imageCount === 0) return;\n    var slot = document.querySelector('.thumb[data-thumb=\"' + p.id + '\"]');\n    if (!slot) return;\n    getMainImage(p.id).then(function (rel) {\n      if (!rel) return;\n      return assetUrl(rel).then(function (url) {\n        if (url && slot.isConnected) { slot.style.backgroundImage = 'url(\"' + url + '\")'; slot.textContent = ''; }\n      });\n    });\n  }\n\n  // Cached image-list fetch — reused by the grid thumbnail AND the detail\n  // sheet, so opening a product you already saw a thumb for is instant.\n  function getImageList(productId) {\n    if (imgListCache[productId]) return Promise.resolve(imgListCache[productId]);\n    return rpc('images:listByProduct', productId)\n      .then(function (imgs) { imgListCache[productId] = imgs || []; return imgListCache[productId]; })\n      .catch(function () { return []; });\n  }\n\n  function getMainImage(productId) {\n    if (mainImgCache[productId] !== undefined) return Promise.resolve(mainImgCache[productId]);\n    return getImageList(productId).then(function (imgs) {\n      var m = imgs && imgs[0];\n      var rel = m ? ((m.isProcessed && m.processedFilepath) ? m.processedFilepath : m.filepath) : null;\n      mainImgCache[productId] = rel;\n      return rel;\n    });\n  }\n\n  /* ── detail sheet ──────────────────────────────────────────── */\n  function openDetail(p) {\n    currentDetail = p;\n    document.getElementById('detailSku').textContent = p.sku || '(no SKU)';\n    var fields = document.getElementById('detailFields');\n    fields.innerHTML = '';\n    document.getElementById('detail').classList.add('open');\n    document.body.style.overflow = 'hidden';\n\n    // Resolve category id → human name via the per-company map we loaded at\n    // boot. Price is the retail figure; formatted with two decimals when set.\n    var catName = p.categoryId && state.categoriesById ? state.categoriesById[p.categoryId] : null;\n    var priceR = (p.priceRetail != null && p.priceRetail !== '') ? ('$' + Number(p.priceRetail).toFixed(2)) : null;\n    var rows = [\n      ['Name', p.name], ['Category', catName], ['Color / finish', p.colorFinish],\n      ['Price', priceR], ['Barcode', p.barcode],\n      ['Status', p.status], ['Images', p.imageCount],\n    ].filter(function (r) { return r[1] != null && r[1] !== ''; });\n    fields.innerHTML = rows.map(function (r) {\n      return '<div class=\"row\"><span class=\"k\">' + escapeHtml(r[0]) + '</span><span class=\"v\">' + escapeHtml(String(r[1])) + '</span></div>';\n    }).join('');\n\n    renderGallery(p.id);\n    renderAiResults(p.id); // v0.47.0\n  }\n\n  function renderGallery(productId) {\n    var gal = document.getElementById('detailGallery');\n    gal.innerHTML = '<div class=\"loading\">Loading images…</div>';\n    getImageList(productId).then(function (imgs) {\n      if (!imgs || !imgs.length) { gal.innerHTML = '<div class=\"empty\">No images yet — tap “Add photo”.</div>'; return; }\n      gal.innerHTML = '';\n      var total = imgs.length;\n      imgs.forEach(function (img, i) {\n        var rel = (img.isProcessed && img.processedFilepath) ? img.processedFilepath : img.filepath;\n        var fig = document.createElement('figure');\n        // v0.49.12: stamp the filepath so refreshSelectedTileClasses() can\n        // toggle .is-selected without a full re-render.\n        fig.setAttribute('data-filepath', img.filepath);\n        var size = img.fileSize ? fmtBytes(img.fileSize) : '';\n        // v0.47.0: replaced the × delete with a ⋯ menu — set-main / use-with-AI /\n        // delete all hang off the same opener so the tile corner stays clean.\n        // v0.49.8: ← → reorder buttons at bottom corners. Disabled at boundaries\n        // (first tile can\\'t go earlier, last tile can\\'t go later). CSS hides\n        // them entirely for Viewer / Photographer roles.\n        // v0.49.12: select-badge — empty circle when select-mode is on but\n        // this tile isn\\'t selected; filled ✓ when selected. CSS handles the\n        // show/hide based on body.is-selecting.\n        var leftDis  = i === 0         ? ' disabled' : '';\n        var rightDis = i === total - 1 ? ' disabled' : '';\n        fig.innerHTML = '<div class=\"thumb\" style=\"aspect-ratio:1\"></div>' +\n          '<span class=\"select-badge\" aria-hidden=\"true\">✓</span>' +\n          '<button class=\"tile-menu\" type=\"button\" aria-label=\"Image actions\">⋯</button>' +\n          '<button class=\"tile-arrow left\"  type=\"button\" aria-label=\"Move earlier\"' + leftDis  + '>‹</button>' +\n          '<button class=\"tile-arrow right\" type=\"button\" aria-label=\"Move later\"'   + rightDis + '>›</button>' +\n          '<figcaption><span>#' + (i + 1) + (i === 0 ? ' · main' : '') + '</span><span>' + size + '</span></figcaption>';\n        gal.appendChild(fig);\n        // Apply the selection style if this tile was already in the Set\n        // (e.g. user rotated to another image and came back).\n        if (state.selected.has(img.filepath)) fig.classList.add('is-selected');\n        var menuBtn = fig.querySelector('.tile-menu');\n        menuBtn.addEventListener('click', function (ev) {\n          ev.stopPropagation();\n          openTileMenu({ productId: productId, filepath: img.filepath, index: i, isMain: i === 0, sku: (currentDetail && currentDetail.sku) || '' });\n        });\n        // v0.49.8: reorder by swapping with the neighbor. Server enforces the\n        // permutation check on `images:reorderImages`, so an invalid order\n        // throws and we don\\'t mutate state until the response comes back.\n        fig.querySelector('.tile-arrow.left').addEventListener('click', function (ev) {\n          ev.stopPropagation();\n          if (i > 0) reorderImageNeighbor(productId, imgs, i, i - 1);\n        });\n        fig.querySelector('.tile-arrow.right').addEventListener('click', function (ev) {\n          ev.stopPropagation();\n          if (i < total - 1) reorderImageNeighbor(productId, imgs, i, i + 1);\n        });\n        // v0.49.12: long-press to enter multi-select. 500ms hold without\n        // movement > 10px triggers it. Cancelled on pointerup (it\\'s a tap)\n        // or significant pointermove (it\\'s a scroll). suppressNextClick\n        // keeps the click handler from immediately deselecting the tile we\n        // just selected via the long-press itself.\n        var lpTimer = null, lpStartX = 0, lpStartY = 0;\n        fig.addEventListener('pointerdown', function (ev) {\n          if (isSelecting() || !isWriter()) return; // no LP needed in select mode\n          lpStartX = ev.clientX; lpStartY = ev.clientY;\n          if (lpTimer) clearTimeout(lpTimer);\n          lpTimer = setTimeout(function () {\n            lpTimer = null;\n            state.suppressNextClick = true;\n            enterSelectMode(img.filepath);\n          }, 500);\n        });\n        function cancelLP(ev) {\n          if (!lpTimer) return;\n          if (ev && ev.type === 'pointermove') {\n            if (Math.abs(ev.clientX - lpStartX) <= 10 && Math.abs(ev.clientY - lpStartY) <= 10) return;\n          }\n          clearTimeout(lpTimer); lpTimer = null;\n        }\n        fig.addEventListener('pointermove',   cancelLP);\n        fig.addEventListener('pointerup',     cancelLP);\n        fig.addEventListener('pointercancel', cancelLP);\n        fig.addEventListener('pointerleave',  cancelLP);\n        // v0.49.5 + v0.49.12: tap the tile → open lightbox OR toggle the\n        // selection if we\\'re in select-mode. ⋯ + arrows stopPropagation so\n        // they don\\'t double-fire here.\n        fig.addEventListener('click', function () {\n          if (state.suppressNextClick) { state.suppressNextClick = false; return; }\n          if (isSelecting()) toggleSelected(img.filepath);\n          else               openImgPreview(imgs, i);\n        });\n        assetUrl(rel).then(function (url) {\n          if (!url) return;\n          var im = document.createElement('img'); im.src = url; im.alt = '';\n          fig.replaceChild(im, fig.firstChild);\n        });\n      });\n    }).catch(function (e) { gal.innerHTML = '<div class=\"empty\">' + escapeHtml(e.message) + '</div>'; });\n  }\n\n  /* ── v0.49.12: multi-select inside one product\\'s gallery ──────\n     Enters via long-press (writer roles only). In select mode, tap any\n     tile toggles its selection; the per-tile ⋯ + arrows hide; the\n     Reframe sheet (and future Enhance / Overlay) shows \"Selected (N)\"\n     as a third scope option. Tap Done to exit; selection clears.\n     Selection is a Set of filepaths so it survives reorders. */\n  function isSelecting() { return !!state.selectMode; }\n  function selectionCount() { return state.selected.size; }\n  function selectionFilepaths() {\n    var out = [];\n    state.selected.forEach(function (fp) { out.push(fp); });\n    return out;\n  }\n\n  function enterSelectMode(firstFilepath) {\n    if (!isWriter()) return;\n    state.selectMode = true;\n    state.selected.clear();\n    if (firstFilepath) state.selected.add(firstFilepath);\n    document.body.classList.add('is-selecting');\n    updateSelectionBar();\n    refreshSelectedTileClasses();\n  }\n  function exitSelectMode() {\n    state.selectMode = false;\n    state.selected.clear();\n    document.body.classList.remove('is-selecting');\n    updateSelectionBar();\n    refreshSelectedTileClasses();\n  }\n  function toggleSelected(filepath) {\n    if (!isSelecting()) return;\n    if (state.selected.has(filepath)) state.selected.delete(filepath);\n    else                              state.selected.add(filepath);\n    updateSelectionBar();\n    refreshSelectedTileClasses();\n  }\n  function updateSelectionBar() {\n    var n = selectionCount();\n    document.getElementById('selectionCount').textContent =\n      n === 0 ? 'Tap tiles to select' : (n + ' selected');\n  }\n  // Cheap re-paint of just the `.is-selected` class on each visible tile\n  // — avoids a full renderGallery() round-trip (which would re-fetch\n  // assetUrls and flicker the thumbs). The data-filepath attribute on each\n  // figure is the link back.\n  function refreshSelectedTileClasses() {\n    var figs = document.querySelectorAll('#detailGallery figure');\n    figs.forEach(function (fig) {\n      var fp = fig.getAttribute('data-filepath');\n      fig.classList.toggle('is-selected', !!fp && state.selected.has(fp));\n    });\n  }\n  document.getElementById('selectAllBtn').addEventListener('click', function () {\n    if (!currentDetail) return;\n    getImageList(currentDetail.id).then(function (imgs) {\n      state.selected = new Set(imgs.map(function (x) { return x.filepath; }));\n      updateSelectionBar();\n      refreshSelectedTileClasses();\n    });\n  });\n  document.getElementById('selectDoneBtn').addEventListener('click', exitSelectMode);\n\n  /* ── v0.49.8: reorder by neighbor swap ─────────────────────────\n     Build the desired permutation as a filepath array, fire\n     `images:reorderImages`, then bust caches and re-render. Server is\n     authoritative — if the permutation is invalid the RPC throws and we\n     don\\'t mutate UI state. Position 0 ↔ \"main\", so swapping with index 0\n     changes the main image just like Set as main does. */\n  function reorderImageNeighbor(productId, imgs, from, to) {\n    if (!imgs || from < 0 || to < 0 || from >= imgs.length || to >= imgs.length) return;\n    var next = imgs.slice();\n    var tmp = next[from]; next[from] = next[to]; next[to] = tmp;\n    var newOrder = next.map(function (x) { return x.filepath; });\n    rpc('images:reorderImages', { productId: productId, newOrder: newOrder })\n      .then(function () {\n        // Same blob-cache logic as Set-as-main: position numbers in basenames\n        // (sku-001.jpg → sku-002.jpg) shift, so every filepath under this\n        // product is potentially stale. Cheapest correct thing: nuke the lot.\n        for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n        delete imgListCache[productId]; delete mainImgCache[productId];\n        renderGallery(productId);\n        // No toast — the visual swap is the feedback. Reorder happens a lot;\n        // a toast per click would be noise.\n      })\n      .catch(function (e) { toast('Reorder failed: ' + e.message); });\n  }\n\n  /* ── v0.49.8: scope picker ────────────────────────────────────\n     The single entry point every destructive edit goes through. Pass:\n       {action, productId, imgs, focusedIndex, danger, hint, onPick}\n     `imgs` is the current list from getImageList. `focusedIndex` is the\n     image the user tapped (for \"This image\"). `danger:true` colors the\n     hint orange and adds the \"no undo\" warning by default.\n     `onPick(filepaths)` is invoked with the chosen image set after the\n     user picks — empty == \"All N images\". v0.49.9 will add the \"Selected\"\n     row sourced from the multi-select state. */\n  function openScopePicker(opts) {\n    if (!opts || !opts.imgs || !opts.imgs.length) return;\n    var imgs = opts.imgs;\n    var focusedIndex = (opts.focusedIndex != null) ? opts.focusedIndex : 0;\n    var focusedImg = imgs[focusedIndex] || imgs[0];\n    document.getElementById('scopeSheetTitle').textContent = opts.action + ' — apply to';\n    var hint = document.getElementById('scopeSheetHint');\n    var hintTxt = opts.hint || '';\n    if (opts.danger) hintTxt = (hintTxt ? hintTxt + ' ' : '') + 'Overwrites the original — no undo.';\n    hint.textContent = hintTxt;\n    hint.classList.toggle('is-danger', !!opts.danger);\n\n    var list = document.getElementById('scopeSheetList');\n    list.innerHTML = '';\n    function row(label, sub, onClick) {\n      var r = document.createElement('div');\n      r.className = 'sheet-row';\n      r.innerHTML = '<span><strong>' + escapeHtml(label) + '</strong>'\n                  + (sub ? '<br><span style=\"color:var(--muted);font-size:12px\">' + escapeHtml(sub) + '</span>' : '')\n                  + '</span>';\n      r.addEventListener('click', onClick);\n      return r;\n    }\n    list.appendChild(row(\n      'This image (#' + (focusedIndex + 1) + (focusedIndex === 0 ? ' · main' : '') + ')',\n      '1 image',\n      function () { closeSheet('scopeSheet'); opts.onPick([focusedImg.filepath]); }\n    ));\n    // v0.49.12: third option when there\\'s a multi-selection. Inserted\n    // between \"This image\" and \"All images\" so the list reads\n    // narrowest → widest.\n    if (isSelecting() && selectionCount() > 0) {\n      var selPaths = imgs.map(function (x) { return x.filepath; })\n                         .filter(function (fp) { return state.selected.has(fp); });\n      if (selPaths.length) {\n        list.appendChild(row(\n          'Selected (' + selPaths.length + ')',\n          selPaths.length + ' image' + (selPaths.length === 1 ? '' : 's'),\n          function () { closeSheet('scopeSheet'); opts.onPick(selPaths); }\n        ));\n      }\n    }\n    list.appendChild(row(\n      'All images',\n      imgs.length + ' image' + (imgs.length === 1 ? '' : 's'),\n      function () { closeSheet('scopeSheet'); opts.onPick(imgs.map(function (x) { return x.filepath; })); }\n    ));\n    openSheet('scopeSheet');\n  }\n  document.getElementById('scopeSheetClose').addEventListener('click', function () { closeSheet('scopeSheet'); });\n  document.getElementById('scopeSheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('scopeSheet'); });\n\n  // Tap the × on a gallery tile → confirm → server-side delete → refresh.\n  // Server is authoritative; we just bust the in-page caches and re-render.\n  // The image cap on the product means deletion can only DECREMENT imageCount,\n  // never push it negative; the Math.max guard is a belt-and-braces clamp.\n  function confirmAndDeleteImage(productId, filepath, index) {\n    var label = '#' + (index + 1) + (index === 0 ? ' (main)' : '');\n    if (!window.confirm('Delete image ' + label + ' from this product?\\n\\nThis can\\'t be undone.')) return;\n    rpc('images:removeFromProduct', { productId: productId, filepath: filepath })\n      .then(function () {\n        for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n        delete imgListCache[productId]; delete mainImgCache[productId];\n        if (currentDetail && currentDetail.id === productId) {\n          currentDetail.imageCount = Math.max(0, (currentDetail.imageCount || 0) - 1);\n        }\n        var prod = state.products.find(function (x) { return x.id === productId; });\n        if (prod) prod.imageCount = Math.max(0, (prod.imageCount || 0) - 1);\n        renderGallery(productId);\n        toast('Image deleted');\n      })\n      .catch(function (e) { toast('Delete failed: ' + e.message); });\n  }\n\n  /* ──────────────────────────────────────────────────────────────\n     v0.47.0: AI flow on mobile\n     ──────────────────────────────────────────────────────────────\n     The full flow: ⋯ menu → \"Use with AI\" → AI sheet (source, prompt,\n     model, variants) → Run → polls ai:listTasks until done → AI gallery\n     section repopulates with the variants for Promote / Delete.\n     Server's role ACL (v0.45.0) enforces write permission; UI hides the\n     menu entirely for Viewer / Photographer.\n     ────────────────────────────────────────────────────────────── */\n\n  // v0.49.6 — quick role check used by tile-menu + AI flow.\n  function isWriter() { return state.role === 'admin' || state.role === 'editor'; }\n\n  /* ── Per-tile ⋯ menu (save / set-main / use-with-AI / delete) ── */\n  function openTileMenu(ctx) {\n    state.aiTileMenuFor = ctx;\n    document.getElementById('tileMenuTitle').textContent = 'Image #' + (ctx.index + 1) + (ctx.isMain ? ' · main' : '');\n    var list = document.getElementById('tileMenuList');\n    list.innerHTML = '';\n    // Save to device — visible to EVERY role. Long-press still works as the\n    // discoverable iOS gesture, but a menu item is more obvious for staff\n    // who don\\'t know about it.\n    list.appendChild(menuRow('⬇  Save image to device', function () {\n      closeSheet('tileMenuSheet');\n      saveImageToDevice(ctx);\n    }));\n    // Writer-only rows. Server enforces with the v0.45.0 ACL; this is just\n    // UI hiding so Viewer / Photographer don\\'t see buttons that would 403.\n    if (isWriter()) {\n      if (!ctx.isMain) {\n        list.appendChild(menuRow('★  Set as main image', function () {\n          closeSheet('tileMenuSheet');\n          rpc('images:setMainImage', { productId: ctx.productId, filepath: ctx.filepath })\n            .then(function () {\n              // Renumbering means filepaths shifted around — bust everything.\n              for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n              delete imgListCache[ctx.productId]; delete mainImgCache[ctx.productId];\n              renderGallery(ctx.productId);\n              toast('Set as main');\n            })\n            .catch(function (e) { toast('Set-main failed: ' + e.message); });\n        }));\n      }\n      list.appendChild(menuRow('✨  Use with AI', function () {\n        closeSheet('tileMenuSheet');\n        openAiSheet({ productId: ctx.productId, filepath: ctx.filepath, index: ctx.index, sku: ctx.sku || '' });\n      }));\n      // v0.49.9: per-image Reframe & crop now opens the Reframe sheet with\n      // scope locked to this specific image — gives the user a live preview\n      // + the tightness/fill/colour controls before committing. The\n      // sheet\\'s \"Apply\" button is the explicit confirm; the destructive\n      // window.confirm we used in v0.49.8 is now redundant.\n      list.appendChild(menuRow('✂︎  Reframe & crop this image', function () {\n        closeSheet('tileMenuSheet');\n        getImageList(ctx.productId).then(function (imgs) {\n          if (!imgs || !imgs.length) { toast('No images to reframe'); return; }\n          openReframeSheet({ productId: ctx.productId, imgs: imgs, focusedIndex: ctx.index, lockScope: true });\n        });\n      }));\n      list.appendChild(menuRow('🗑  Delete', function () {\n        closeSheet('tileMenuSheet');\n        confirmAndDeleteImage(ctx.productId, ctx.filepath, ctx.index);\n      }, true));\n    }\n    openSheet('tileMenuSheet');\n  }\n\n  /* v0.49.6 — save an image to the device. Prefers the iOS share sheet\n     (`navigator.share` with a File) since that surfaces \"Save Image\" right\n     into Photos with one tap. Falls back to a triggered <a download>, which\n     on iOS routes through Files (user can then move to Photos). Either way,\n     no long-press required. */\n  function saveImageToDevice(ctx) {\n    var rel = ctx.filepath || '';\n    if (!rel) { toast('No image to save'); return; }\n    toast('Preparing image…');\n    var enc = rel.split('/').map(encodeURIComponent).join('/');\n    fetch(baseUrl + '/assets/' + enc, { headers: { Authorization: 'Bearer ' + token } })\n      .then(function (res) {\n        if (!res.ok) throw new Error('Server returned ' + res.status);\n        return res.blob();\n      })\n      .then(function (blob) {\n        var ext = (blob.type && blob.type.split('/')[1]) || (rel.split('.').pop() || 'jpg');\n        var sku = (ctx.sku || '').replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') || 'image';\n        var filename = sku + '-' + ((ctx.index || 0) + 1) + '.' + ext;\n        // Try the native share sheet first — iOS shows \"Save Image\" which\n        // saves to Photos directly. canShare() is the gate per spec.\n        var file = null;\n        try { file = new File([blob], filename, { type: blob.type || 'image/jpeg' }); } catch (_) {}\n        if (file && navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {\n          return navigator.share({ files: [file] }).catch(function (e) {\n            // User cancellation isn\\'t an error — only surface real failures.\n            if (e && e.name !== 'AbortError') toast('Share failed: ' + e.message);\n          });\n        }\n        // Fallback: trigger an <a download>. iOS routes this through the\n        // Files app; user can long-press the file → Share → Save Image.\n        var url = URL.createObjectURL(blob);\n        var a = document.createElement('a');\n        a.href = url; a.download = filename;\n        document.body.appendChild(a); a.click(); a.remove();\n        setTimeout(function () { URL.revokeObjectURL(url); }, 0);\n        toast('Downloading…');\n      })\n      .catch(function (e) { toast('Save failed: ' + e.message); });\n  }\n  function menuRow(label, onClick, destructive) {\n    var r = document.createElement('div');\n    r.className = 'sheet-row';\n    if (destructive) r.style.color = '#dc2626';\n    r.textContent = label;\n    r.addEventListener('click', onClick);\n    return r;\n  }\n  document.getElementById('tileMenuClose').addEventListener('click', function () { closeSheet('tileMenuSheet'); });\n  document.getElementById('tileMenuSheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('tileMenuSheet'); });\n\n  /* ── AI sheet (Process with AI) ────────────────────────────── */\n  function openAiSheet(source) {\n    // Source is { productId, filepath, index, sku }. The picked PROMPT + MODEL\n    // are restored from localStorage so the sheet opens ready-to-run for\n    // returning users; the source itself always reflects the tapped image.\n    state.aiPickedSource = source;\n    state.aiPickedPromptBody = null;\n    state.aiPickedPromptName = null;\n    state.aiPickedPromptTemplateId = null;\n    state.aiPickedModel = null;\n\n    // Source thumbnail + meta\n    var thumb = document.getElementById('aiSourceThumb');\n    thumb.style.backgroundImage = '';\n    assetUrl(source.filepath).then(function (url) {\n      if (url) thumb.style.backgroundImage = 'url(\"' + url + '\")';\n    });\n    document.getElementById('aiSourceMeta').innerHTML =\n      '<strong>' + escapeHtml(source.sku || '(no SKU)') + '</strong>' +\n      'Image #' + (source.index + 1) + (source.index === 0 ? ' · main' : '');\n\n    // v0.49.0: restore last-used prompt from localStorage. We trust the\n    // saved BODY even if the templateId is now stale (the user may have\n    // deleted that preset on desktop) — sending raw text always works.\n    document.getElementById('aiPromptValue').textContent = 'Pick a prompt…';\n    try {\n      var savedPrompt = JSON.parse(localStorage.getItem(LS.aiPrompt) || 'null');\n      if (savedPrompt && savedPrompt.body) {\n        state.aiPickedPromptBody = savedPrompt.body;\n        state.aiPickedPromptName = savedPrompt.name || 'Last prompt';\n        state.aiPickedPromptTemplateId = savedPrompt.templateId || null;\n        document.getElementById('aiPromptValue').textContent = state.aiPickedPromptName;\n      }\n    } catch (e) { /* corrupt JSON → fall through to \"Pick a prompt…\" */ }\n\n    // Restore last-used model. We need the model catalog so the in-flight\n    // model object (with displayName + pricing) can be re-attached — not\n    // just the key. Fetch lazily on first open + cache.\n    document.getElementById('aiModelValue').textContent = 'Pick a model…';\n    document.getElementById('aiAspectRow').hidden = true; // shown after a model is picked / restored\n    state.aiPickedSize = null;\n    refreshAiCost(); // shows \"—\" until model is restored / picked\n    var savedKey = localStorage.getItem(LS.aiModelKey) || '';\n    function applySavedModel(models) {\n      if (!savedKey) return;\n      var m = (models || []).find(function (x) { return x.key === savedKey; });\n      if (!m) return; // model was retired in the catalog — leave empty\n      state.aiPickedModel = m;\n      document.getElementById('aiModelValue').textContent =\n        (m.displayName || m.key) + ' · ' + (m.provider || '');\n      renderAspectChips(m); // v0.49.3 — paints the aspect row with the saved choice\n      refreshAiCost();\n      refreshAiRunEnabled();\n    }\n    if (state.aiModels === null) {\n      rpc('ai:listModels').then(function (rows) {\n        state.aiModels = rows || [];\n        applySavedModel(state.aiModels);\n      }).catch(function () { state.aiModels = []; });\n    } else {\n      applySavedModel(state.aiModels);\n    }\n    refreshAiRunEnabled();\n    openSheet('aiSheet');\n  }\n  function refreshAiRunEnabled() {\n    var ok = state.aiPickedPromptBody && state.aiPickedModel && state.aiPickedSource;\n    document.getElementById('aiRunBtn').disabled = !ok;\n  }\n  function refreshAiCost() {\n    var m = state.aiPickedModel;\n    var per = m && m.pricing && m.pricing.perOutputUsd;\n    var el = document.getElementById('aiCost');\n    if (per == null) { el.innerHTML = 'Estimated cost: —'; return; }\n    el.innerHTML = 'Estimated cost: <strong>$' + per.toFixed(3) + '</strong> per run';\n  }\n  document.getElementById('aiSheetClose').addEventListener('click', function () { closeSheet('aiSheet'); });\n  document.getElementById('aiSheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('aiSheet'); });\n\n  /* ── Prompt picker — \"My presets\" + \"Library\" with one-tap adopt ── */\n  document.getElementById('aiPromptPick').addEventListener('click', function () {\n    document.getElementById('aiPromptSearch').value = '';\n    // Load fresh user presets each open so a Save-on-desktop is reflected.\n    rpc('ai:listPrompts', state.companyId).catch(function () { return []; }).then(function (rows) {\n      renderAiPromptSheet('', rows || []);\n    });\n    openSheet('aiPromptSheet');\n    setTimeout(function () { document.getElementById('aiPromptSearch').focus(); }, 80);\n  });\n  function renderAiPromptSheet(query, myPresets) {\n    state.aiMyPresets = myPresets;  // remember for search re-renders\n    var list = document.getElementById('aiPromptList');\n    list.innerHTML = '';\n    var q = (query || '').trim().toLowerCase();\n    function filt(items, getLabel, getBody) {\n      if (!q) return items.slice();\n      return items.filter(function (it) {\n        return (getLabel(it) || '').toLowerCase().indexOf(q) !== -1\n            || (getBody(it) || '').toLowerCase().indexOf(q) !== -1;\n      });\n    }\n    var presets = filt(myPresets, function (p) { return p.name; }, function (p) { return p.body; });\n    var lib = filt(PROMPT_LIBRARY, function (p) { return p.label; }, function (p) { return p.body; });\n\n    if (presets.length) {\n      list.appendChild(groupHead('My presets'));\n      presets.forEach(function (p) {\n        list.appendChild(promptRow(p.name, p.body, function () {\n          pickPrompt({ body: p.body, name: p.name, templateId: p.id });\n        }));\n      });\n    }\n    if (lib.length) {\n      list.appendChild(groupHead('Library'));\n      lib.forEach(function (p) {\n        list.appendChild(promptRow(p.label, p.body, function () {\n          // Adopt into \"My presets\" so it shows up in the user's list next\n          // time — same UX as the desktop's \"Save to my presets\". Non-fatal:\n          // if create fails (rare — e.g. duplicate name) we still use the body.\n          rpc('ai:createPrompt', { companyId: state.companyId, name: p.label, body: p.body })\n            .then(function (saved) {\n              pickPrompt({ body: p.body, name: p.label, templateId: saved && saved.id });\n              toast('Saved \"' + p.label + '\" to your presets');\n            })\n            .catch(function () {\n              pickPrompt({ body: p.body, name: p.label, templateId: null });\n            });\n        }, p.category));\n      });\n    }\n    if (!presets.length && !lib.length) {\n      list.innerHTML = '<div class=\"sheet-empty\">No prompts match “' + escapeHtml(query) + '”.</div>';\n    }\n  }\n  function groupHead(label) {\n    var r = document.createElement('div');\n    r.className = 'sheet-row is-group-head';\n    r.textContent = label;\n    return r;\n  }\n  function promptRow(label, body, onClick, metaText) {\n    var r = document.createElement('div');\n    r.className = 'sheet-row';\n    var html = '<div><strong>' + escapeHtml(label) + '</strong>' +\n      '<span class=\"row-sub\">' + escapeHtml(body) + '</span></div>';\n    if (metaText) html += '<span class=\"row-meta\">' + escapeHtml(metaText) + '</span>';\n    r.innerHTML = html;\n    r.addEventListener('click', onClick);\n    return r;\n  }\n  function pickPrompt(p) {\n    state.aiPickedPromptBody = p.body;\n    state.aiPickedPromptName = p.name;\n    state.aiPickedPromptTemplateId = p.templateId || null;\n    document.getElementById('aiPromptValue').textContent = p.name || 'Prompt picked';\n    // v0.49.0: remember as the per-device default for the next run.\n    try { localStorage.setItem(LS.aiPrompt, JSON.stringify({ body: p.body, name: p.name, templateId: p.templateId || null })); } catch (e) {}\n    closeSheet('aiPromptSheet');\n    refreshAiRunEnabled();\n  }\n  document.getElementById('aiPromptSearch').addEventListener('input', function () {\n    renderAiPromptSheet(this.value, state.aiMyPresets || []);\n  });\n  document.getElementById('aiPromptSheetClose').addEventListener('click', function () { closeSheet('aiPromptSheet'); });\n  document.getElementById('aiPromptSheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('aiPromptSheet'); });\n\n  /* ── Model picker — image-to-image only, with per-output price ── */\n  document.getElementById('aiModelPick').addEventListener('click', function () {\n    var list = document.getElementById('aiModelList');\n    list.innerHTML = '<div class=\"sheet-empty\">Loading models…</div>';\n    var p = state.aiModels === null\n      ? rpc('ai:listModels').then(function (r) { state.aiModels = r || []; return state.aiModels; })\n      : Promise.resolve(state.aiModels);\n    p.then(function (models) { renderAiModelSheet(models); }).catch(function (e) {\n      list.innerHTML = '<div class=\"sheet-empty\">' + escapeHtml(e.message) + '</div>';\n    });\n    openSheet('aiModelSheet');\n  });\n  function renderAiModelSheet(models) {\n    var list = document.getElementById('aiModelList');\n    list.innerHTML = '';\n    // Filter to image-to-image only: a model is i2i if its display name or\n    // key contains \"image-to-image\" / \"edit\" / \"i2i\". Simple + matches the\n    // model catalog conventions in main/ai/models.js.\n    var i2i = (models || []).filter(function (m) {\n      var s = ((m.displayName || '') + ' ' + (m.key || '')).toLowerCase();\n      return s.indexOf('image-to-image') !== -1 || s.indexOf('i2i') !== -1 || s.indexOf('edit') !== -1;\n    });\n    if (!i2i.length) {\n      list.innerHTML = '<div class=\"sheet-empty\">No image-to-image models available.</div>';\n      return;\n    }\n    i2i.forEach(function (m) {\n      var per = m.pricing && m.pricing.perOutputUsd;\n      var price = per != null ? ('$' + per.toFixed(3) + '/img') : '';\n      var r = document.createElement('div');\n      r.className = 'sheet-row';\n      r.innerHTML = '<div><strong>' + escapeHtml(m.displayName || m.key || '') + '</strong>' +\n        '<span class=\"row-sub\">' + escapeHtml(m.provider || '') + '</span></div>' +\n        '<span class=\"row-meta\">' + price + '</span>';\n      r.addEventListener('click', function () { pickModel(m); });\n      list.appendChild(r);\n    });\n  }\n  function pickModel(m) {\n    state.aiPickedModel = m;\n    document.getElementById('aiModelValue').textContent = (m.displayName || m.key || '') + ' · ' + (m.provider || '');\n    // v0.49.0: remember as per-device default for the next run.\n    try { localStorage.setItem(LS.aiModelKey, m.key || ''); } catch (e) {}\n    // v0.49.3: aspect-ratio list depends on the model. Carry over the saved\n    // size when it's in the new model's list; otherwise fall back to the\n    // model's first option.\n    renderAspectChips(m);\n    closeSheet('aiModelSheet');\n    refreshAiCost();\n    refreshAiRunEnabled();\n  }\n\n  // v0.49.3 — build the aspect chip row for the given model. The \"saved\"\n  // preference wins if it's a valid option for THIS model (e.g. switching\n  // from a GPT-Image-2 to Nano Banana doesn't strand the user on an aspect\n  // the model doesn't accept); otherwise use the model's first listed size.\n  function renderAspectChips(m) {\n    var row = document.getElementById('aiAspectRow');\n    var box = document.getElementById('aiAspectChips');\n    box.innerHTML = '';\n    var sizes = (m && Array.isArray(m.sizes)) ? m.sizes : [];\n    if (!sizes.length) { row.hidden = true; state.aiPickedSize = null; return; }\n    row.hidden = false;\n    var saved = '';\n    try { saved = localStorage.getItem(LS.aiSize) || ''; } catch (e) {}\n    var initial = sizes.indexOf(saved) !== -1 ? saved : sizes[0];\n    state.aiPickedSize = initial;\n    sizes.forEach(function (s) {\n      var btn = document.createElement('button');\n      btn.type = 'button';\n      btn.textContent = s;\n      btn.setAttribute('role', 'radio');\n      btn.setAttribute('aria-checked', String(s === initial));\n      if (s === initial) btn.classList.add('is-active');\n      btn.addEventListener('click', function () {\n        state.aiPickedSize = s;\n        try { localStorage.setItem(LS.aiSize, s); } catch (e) {}\n        box.querySelectorAll('button').forEach(function (x) {\n          x.classList.toggle('is-active', x === btn);\n          x.setAttribute('aria-checked', String(x === btn));\n        });\n      });\n      box.appendChild(btn);\n    });\n  }\n  document.getElementById('aiModelSheetClose').addEventListener('click', function () { closeSheet('aiModelSheet'); });\n  document.getElementById('aiModelSheet').addEventListener('click', function (e) { if (e.target === this) closeSheet('aiModelSheet'); });\n\n  /* ── Run → queue the task → start polling ──────────────────── */\n  document.getElementById('aiRunBtn').addEventListener('click', function () {\n    if (!state.aiPickedPromptBody || !state.aiPickedModel || !state.aiPickedSource) return;\n    var btn = this; btn.disabled = true; btn.textContent = 'Queueing…';\n    var src = state.aiPickedSource;\n    var m = state.aiPickedModel;\n    var args = {\n      companyId: state.companyId,\n      productId: src.productId,\n      sourceImagePath: src.filepath,\n      provider: m.provider,\n      model: m.key,\n      prompt: state.aiPickedPromptBody,\n      promptTemplateId: state.aiPickedPromptTemplateId || null,\n      // v0.48.0: every variant auto-adds to the product as a new image. Mobile\n      // users don't get a separate \"review & promote\" step — they just see the\n      // results land in the regular gallery and can ⋯ → Set as main / Delete\n      // from there. autoAddToProduct (not autoPromoteAsMain) means we don't\n      // disrupt the existing main image; new variants append at the end.\n      // v0.49.0: always 1 variant per tap on mobile — predictable per-run cost,\n      // fat-finger protection. Want another? Tap Run again.\n      // v0.49.3: include the picked aspect ratio (`size`) so we don't fall\n      // through to the model's provider default (which defaulted to 1:1 on\n      // some models but not all — output dimensions were silently wrong).\n      options: { nVariants: 1, numImages: 1, autoAddToProduct: true, size: state.aiPickedSize || undefined },\n    };\n    rpc('ai:queueTask', args)\n      .then(function () {\n        toast('Queued — check back in 30–60s');\n        closeSheet('aiSheet');\n        startAiPolling(src.productId);\n        refreshAiBadge(); // v0.49.2 — bump the appbar badge immediately\n      })\n      .catch(function (e) { toast('Queue failed: ' + e.message); })\n      .finally(function () { btn.disabled = false; btn.textContent = '✨ Run AI'; refreshAiRunEnabled(); });\n  });\n\n  /* ── AI section: status-only banner + polling + Repair ───────\n     v0.48.0: variants auto-add to the product (autoAddToProduct), so the\n     section doesn't list completed items or offer Promote / Remove. It\n     shows: (a) a pulse while a task is in flight, (b) a Repair button per\n     failed task (provider didn't return an image — the desktop's Repair\n     flow re-fetches without spending fresh credit). On the pending → done\n     transition the regular gallery refreshes so new variants are visible. */\n  function renderAiResults(productId) {\n    var box = document.getElementById('aiResults');\n    rpc('ai:listTasks', { companyId: state.companyId, limit: 20, statuses: ['queued','running','done','failed'] })\n      .catch(function () { return []; })\n      .then(function (tasks) {\n        var mine = (tasks || []).filter(function (t) { return t.productId === productId; });\n        var pending = mine.filter(function (t) { return t.status === 'queued' || t.status === 'running'; });\n        var broken = mine.filter(function (t) { return t.status === 'failed'; });\n        var hadPending = state.aiHadPendingFor === productId;\n\n        // Pending → done transition: refresh the regular gallery so the\n        // freshly auto-added variants appear immediately.\n        if (hadPending && !pending.length) {\n          for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n          delete imgListCache[productId]; delete mainImgCache[productId];\n          renderGallery(productId);\n          if (!broken.length) toast('AI generation done');\n        }\n\n        if (!pending.length && !broken.length) {\n          state.aiHadPendingFor = null;\n          box.classList.add('empty');\n          box.innerHTML = '';\n          stopAiPolling();\n          return;\n        }\n\n        state.aiHadPendingFor = pending.length ? productId : null;\n        box.classList.remove('empty');\n        var html = '<h4>AI activity</h4>';\n        if (pending.length) {\n          html += '<div class=\"ai-status\"><span class=\"dot\"></span>' +\n            ' Generating ' + pending.length + ' variant' + (pending.length === 1 ? '' : 's') +\n            '… results land in the gallery below in 30–60s.</div>';\n        }\n        broken.forEach(function (t) {\n          var reason = t.errorMessage ? escapeHtml(t.errorMessage) : 'Provider didn\\'t return an image';\n          html += '<div class=\"ai-status ai-broken\">' +\n            '<div>⚠ ' + reason + '</div>' +\n            '<button class=\"btn btn--primary ai-repair\" data-id=\"' + escapeHtml(t.id) + '\">Repair (no extra credit)</button>' +\n          '</div>';\n        });\n        box.innerHTML = html;\n        box.querySelectorAll('.ai-repair').forEach(function (b) {\n          b.addEventListener('click', function () { repairAiTask(b.getAttribute('data-id'), b); });\n        });\n        // Keep polling whenever ANYTHING is in flight; broken tasks alone\n        // don't need a polling loop (state is stable until user repairs).\n        if (pending.length) startAiPolling(productId);\n        else stopAiPolling();\n      });\n  }\n  function repairAiTask(taskId, btn) {\n    if (!taskId) return;\n    if (btn) { btn.disabled = true; btn.textContent = 'Repairing…'; }\n    rpc('ai:repairTask', taskId)\n      .then(function () {\n        toast('Repair queued — checking again');\n        if (currentDetail) renderAiResults(currentDetail.id);\n        refreshAiBadge(); // v0.49.2 — failed dropped to running, may flip back\n      })\n      .catch(function (e) { toast('Repair failed: ' + e.message); })\n      .finally(function () {\n        if (btn) { btn.disabled = false; btn.textContent = 'Repair (no extra credit)'; }\n      });\n  }\n\n  /* ── v0.49.1: manual refresh ────────────────────────────────\n     The web viewer doesn't subscribe to the WebSocket event bus the desktop\n     uses, so a remote edit doesn't push down. This bust-everything reload\n     covers it: clear blob/list caches, then re-fetch products, the open\n     detail's gallery, and the AI status. Spins the icon while it works. */\n  function refreshNow() {\n    var btn = document.getElementById('refreshBtn');\n    btn.classList.add('is-spinning');\n    // Drop all in-memory caches.\n    for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n    for (var p in imgListCache) delete imgListCache[p];\n    for (var p2 in mainImgCache) delete mainImgCache[p2];\n    var jobs = [];\n    // Reload products (always — the grid behind any open sheet still needs it).\n    if (state.companyId) {\n      jobs.push(\n        rpc('products:list', { companyId: state.companyId, filters: {} })\n          .then(function (rows) { state.products = rows || []; applyFilter(); render(); })\n          .catch(function () {})\n      );\n    }\n    // Reload the open detail if any (gallery + AI section + product fields).\n    if (currentDetail && document.getElementById('detail').classList.contains('open')) {\n      renderGallery(currentDetail.id);\n      renderAiResults(currentDetail.id);\n    }\n    refreshAiBadge(); // v0.49.2 — keep the badge fresh after a manual refresh\n    Promise.all(jobs).finally(function () {\n      // Brief minimum spin so the user sees feedback even when the round-trip\n      // is instant on a fast network.\n      setTimeout(function () { btn.classList.remove('is-spinning'); }, 500);\n    });\n  }\n  document.getElementById('refreshBtn').addEventListener('click', refreshNow);\n\n  /* ── v0.49.2: global AI activity (badge + sheet) ────────────\n     The badge counts queued + running + failed across the whole company so\n     the user knows there's outstanding work even when browsing elsewhere.\n     The sheet lists every task with source-image thumb, SKU, prompt + model\n     label, and a status pill. Tap a row → close the sheet + open that\n     product's detail. Failed rows include an inline Repair button (same\n     no-extra-credit flow as the per-product Repair). */\n\n  state.aiActivityPollTimer = null;\n\n  function refreshAiBadge() {\n    if (!state.companyId) return;\n    rpc('ai:listTasks', { companyId: state.companyId, limit: 50, statuses: ['queued','running','failed'] })\n      .catch(function () { return []; })\n      .then(function (tasks) {\n        var n = (tasks || []).length;\n        var b = document.getElementById('aiActivityBadge');\n        if (n > 0) { b.textContent = n > 99 ? '99+' : String(n); b.hidden = false; }\n        else { b.hidden = true; }\n      });\n  }\n\n  function openAiActivity() {\n    renderAiActivity(); // immediate paint\n    openSheet('aiActivitySheet');\n    // Live-poll while the sheet is open so status pills flip queued→running→done\n    // (done items drop out of the list) without the user pulling-to-refresh.\n    if (state.aiActivityPollTimer) clearInterval(state.aiActivityPollTimer);\n    state.aiActivityPollTimer = setInterval(renderAiActivity, 6000);\n  }\n  function closeAiActivity() {\n    closeSheet('aiActivitySheet');\n    if (state.aiActivityPollTimer) { clearInterval(state.aiActivityPollTimer); state.aiActivityPollTimer = null; }\n    refreshAiBadge(); // catch any state changes the poll missed\n  }\n  document.getElementById('aiActivityBtn').addEventListener('click', openAiActivity);\n  document.getElementById('aiActivitySheetClose').addEventListener('click', closeAiActivity);\n  document.getElementById('aiActivitySheet').addEventListener('click', function (e) { if (e.target === this) closeAiActivity(); });\n\n  function renderAiActivity() {\n    var list = document.getElementById('aiActivityList');\n    if (!state.companyId) { list.innerHTML = '<div class=\"sheet-empty\">No company selected.</div>'; return; }\n    rpc('ai:listTasks', { companyId: state.companyId, limit: 50, statuses: ['queued','running','failed'] })\n      .catch(function () { return []; })\n      .then(function (tasks) {\n        tasks = tasks || [];\n        // Update the badge from this same fetch so we don't burn an extra call.\n        var b = document.getElementById('aiActivityBadge');\n        if (tasks.length > 0) { b.textContent = tasks.length > 99 ? '99+' : String(tasks.length); b.hidden = false; }\n        else { b.hidden = true; }\n        if (!tasks.length) {\n          list.innerHTML = '<div class=\"sheet-empty\">No AI tasks in flight. ✨</div>';\n          return;\n        }\n        list.innerHTML = '';\n        tasks.forEach(function (t) {\n          var p = state.products.find(function (x) { return x.id === t.productId; });\n          var sku = (p && p.sku) || t.productId || '(no product)';\n          var prompt = (t.prompt || '').replace(/\\s+/g, ' ').slice(0, 80);\n          var statusClass = 'pill--' + (t.status || 'queued');\n          var failed = t.status === 'failed';\n          var row = document.createElement('div');\n          row.className = 'sheet-row ai-activity-row' + (failed ? ' is-failed' : '');\n          row.innerHTML =\n            '<div class=\"thumb\" data-rel=\"' + escapeHtml(t.sourceImagePath || '') + '\"></div>' +\n            '<div class=\"meta\">' +\n              '<strong>' + escapeHtml(sku) + '</strong>' +\n              '<span class=\"sub\">' + escapeHtml(prompt) + (prompt.length === 80 ? '…' : '') + '</span>' +\n            '</div>' +\n            '<span class=\"pill ' + statusClass + '\">' + escapeHtml(t.status || '') + '</span>' +\n            (failed ? '<div class=\"repair-line\"><button class=\"btn btn--primary ai-repair\" data-id=\"' + escapeHtml(t.id) + '\">Repair (no extra credit)</button></div>' : '');\n          // Row tap → close the sheet + open that product's detail. Skip\n          // when the tap lands on the Repair button (separate handler below).\n          row.addEventListener('click', function (ev) {\n            if (ev.target.closest('.ai-repair')) return;\n            jumpToProductDetail(t.productId);\n          });\n          list.appendChild(row);\n          // Lazy-paint the source thumb. Don't block the list render on N\n          // round-trips — each one's async, browser draws as they arrive.\n          if (t.sourceImagePath) {\n            assetUrl(t.sourceImagePath).then(function (url) {\n              if (url) { row.querySelector('.thumb').style.backgroundImage = 'url(\"' + url + '\")'; }\n            });\n          }\n        });\n        list.querySelectorAll('.ai-repair').forEach(function (b) {\n          b.addEventListener('click', function (ev) {\n            ev.stopPropagation();\n            repairAiTask(b.getAttribute('data-id'), b);\n            // After repair, repaint the sheet so the row's status updates.\n            setTimeout(renderAiActivity, 400);\n          });\n        });\n      });\n  }\n\n  // Tap a row → open that product's detail. We have the productId only;\n  // look up the local copy if it's on the current page, otherwise fetch\n  // it. Either way we close the activity sheet first so the navigation\n  // feels snappy and there's no overlay pile-up.\n  function jumpToProductDetail(productId) {\n    closeAiActivity();\n    var p = state.products.find(function (x) { return x.id === productId; });\n    if (p) { openDetail(p); return; }\n    rpc('products:get', productId)\n      .then(function (fetched) {\n        if (fetched) openDetail(fetched);\n        else toast('Product no longer exists');\n      })\n      .catch(function (e) { toast('Could not open product: ' + e.message); });\n  }\n  function startAiPolling(productId) {\n    stopAiPolling();\n    state.aiPollTimer = setInterval(function () {\n      if (!currentDetail || currentDetail.id !== productId) { stopAiPolling(); return; }\n      renderAiResults(productId);\n    }, 6000);\n  }\n  function stopAiPolling() {\n    if (state.aiPollTimer) { clearInterval(state.aiPollTimer); state.aiPollTimer = null; }\n  }\n\n  /* ── add photos (camera / library) ─────────────────────────── */\n  function extFromType(file) {\n    var t = (file.type || '').toLowerCase();\n    if (t.indexOf('png') !== -1) return '.png';\n    if (t.indexOf('webp') !== -1) return '.webp';\n    if (t.indexOf('heic') !== -1 || t.indexOf('heif') !== -1) return '.heic';\n    return '.jpg'; // iOS usually hands us JPEG from the library/camera anyway\n  }\n  function fileToB64(file) {\n    return new Promise(function (resolve, reject) {\n      var r = new FileReader();\n      r.onload = function () { var s = String(r.result); resolve(s.slice(s.indexOf(',') + 1)); };\n      r.onerror = function () { reject(new Error('Could not read the photo')); };\n      r.readAsDataURL(file);\n    });\n  }\n  function handleAddPhotos(files) {\n    if (!currentDetail || !files || !files.length) return;\n    var pid = currentDetail.id;\n    var arr = Array.prototype.slice.call(files);\n    var btn = document.getElementById('addPhotoBtn');\n    btn.disabled = true;\n    var added = 0, dup = 0, failed = 0;\n    function finish() {\n      btn.disabled = false; btn.textContent = '＋ Add photo';\n      delete imgListCache[pid]; delete mainImgCache[pid];\n      currentDetail.imageCount = (currentDetail.imageCount || 0) + added;\n      var prod = state.products.find(function (x) { return x.id === pid; });\n      if (prod) prod.imageCount = (prod.imageCount || 0) + added;\n      renderGallery(pid);\n      var msg = added + ' photo' + (added === 1 ? '' : 's') + ' added';\n      if (dup) msg += ', ' + dup + ' already there';\n      if (failed) msg += ', ' + failed + ' failed';\n      toast(msg);\n    }\n    function next(i) {\n      if (i >= arr.length) return finish();\n      btn.textContent = 'Uploading ' + (i + 1) + '/' + arr.length + '…';\n      fileToB64(arr[i])\n        .then(function (b64) {\n          return rpc('images:importFromBytes', { productId: pid, bytes: { __bin: true, b64: b64 }, ext: extFromType(arr[i]) });\n        })\n        .then(function (res) { if (res && res.skipped) dup++; else added++; })\n        .catch(function (e) { failed++; toast('Upload failed: ' + e.message); })\n        .then(function () { next(i + 1); });\n    }\n    next(0);\n  }\n  document.getElementById('addPhotoBtn').addEventListener('click', function () {\n    document.getElementById('photoInput').click();\n  });\n\n  /* ── v0.49.8: Reframe & crop ─────────────────────────────────\n     Was \"Auto-crop.\" Now goes through the scope picker first instead of\n     silently running on every image. Trims the background border around the\n     product and reframes to a uniform white-background look — best on solid\n     / white backgrounds. Destructive (overwrites in place).\n     \"This image\" sends the focused image (defaults to the main / first) via\n     the new `filepaths` filter on `images:autoCropProducts`. \"All images\"\n     omits the filter so the IPC keeps its original loop behavior. */\n  document.getElementById('autoCropBtn').addEventListener('click', function () {\n    if (!currentDetail) return;\n    var pid = currentDetail.id;\n    getImageList(pid).then(function (imgs) {\n      if (!imgs || !imgs.length) { toast('No images to reframe'); return; }\n      // v0.49.9: opens the new Reframe sheet (live preview + controls) instead\n      // of the bare scope picker. Header entry defaults to lockScope=false so\n      // the user can toggle between Main and All inside the sheet.\n      openReframeSheet({ productId: pid, imgs: imgs, focusedIndex: 0, lockScope: false });\n    });\n  });\n\n  function runReframeCrop(pid, filepaths, opts) {\n    opts = opts || {};\n    var btn = document.getElementById('autoCropBtn');\n    var n = filepaths.length;\n    btn.disabled = true; btn.textContent = 'Cropping ' + n + '…';\n    rpc('images:autoCropProducts', {\n      productIds: [pid],\n      // Empty array would mean \"no images\" — only pass the key when we want to filter.\n      filepaths: filepaths,\n      // v0.49.9: tightness/fill/colour now come from the Reframe sheet\n      // instead of being hard-coded defaults. Server still clamps these.\n      scale:         opts.scale         != null ? opts.scale         : 0.88,\n      fillMode:      opts.fillMode      || 'color',\n      fillColor:     opts.fillColor     || '#FFFFFF',\n      trimThreshold: opts.trimThreshold != null ? opts.trimThreshold : 12,\n    })\n      .then(function (res) {\n        var done = (res && res.images) || 0;\n        var failed = (res && res.failed) || 0;\n        // Auto-crop overwrites files in place (same relpath, new bytes), so the\n        // blob-URL cache (keyed by relpath) would serve stale pixels. Revoke +\n        // clear it so the gallery + grid thumbs re-fetch. Server sends /assets\n        // with Cache-Control: no-store (v0.49.4), so the refetch gets new bytes.\n        for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n        delete imgListCache[pid]; delete mainImgCache[pid];\n        renderGallery(pid);\n        toast(failed\n          ? ('Reframed ' + done + ', ' + failed + ' failed')\n          : ('Reframed ' + done + ' image' + (done === 1 ? '' : 's')));\n      })\n      .catch(function (e) { toast('Reframe failed: ' + e.message); })\n      .finally(function () { btn.disabled = false; btn.textContent = '✂︎ Reframe & crop'; });\n  }\n\n  /* ── v0.49.9: Reframe & crop sheet ────────────────────────────\n     Replaces the bare scope picker for this action so users can SEE the\n     result and TUNE the knobs (tightness, fill mode, fill colour) before\n     committing. Live preview via `images:reframePreview`. */\n\n  // Tightness → scale mapping. Snug = product fills more of the canvas;\n  // Loose = more breathing room. \"Normal\" matches the v0.49.8 default (0.88).\n  var REFRAME_TIGHTNESS = [\n    { key: 'snug',   label: 'Snug',   scale: 0.95 },\n    { key: 'normal', label: 'Normal', scale: 0.88 },\n    { key: 'loose', label: 'Loose',  scale: 0.78 },\n  ];\n  var REFRAME_FILLS = [\n    { key: 'color', label: 'Solid colour' },\n    { key: 'blur',  label: 'Blur edges' },\n  ];\n  var REFRAME_COLORS = [\n    { key: '#FFFFFF', label: 'White' },\n    { key: '#000000', label: 'Black' },\n    { key: '#EAEAEA', label: 'Light grey' },\n  ];\n\n  function reframeOpt(arr, key) {\n    for (var i = 0; i < arr.length; i++) if (arr[i].key === key) return arr[i];\n    return arr[0];\n  }\n  // Decode the `{__bin:true, b64}` envelope into a Blob URL we can drop on\n  // an <img>. Mirrors how the AI variants render. Caller is responsible for\n  // revoking the URL when it\\'s replaced or the sheet closes.\n  function envelopeToBlobUrl(env, mime) {\n    if (!env || env.__bin !== true || typeof env.b64 !== 'string') return null;\n    try {\n      var bin = atob(env.b64);\n      var len = bin.length;\n      var u8 = new Uint8Array(len);\n      for (var i = 0; i < len; i++) u8[i] = bin.charCodeAt(i);\n      return URL.createObjectURL(new Blob([u8], { type: mime || 'image/png' }));\n    } catch (_) { return null; }\n  }\n\n  function openReframeSheet(o) {\n    if (!o || !o.imgs || !o.imgs.length) return;\n    var focusedIndex = (o.focusedIndex != null) ? o.focusedIndex : 0;\n    // Lock scope when entered from the ⋯ menu — the user already picked the\n    // specific image, so we don\\'t make them pick a scope on top of that.\n    var lockScope = !!o.lockScope;\n    // v0.49.12: if there\\'s an active multi-selection AND the user didn\\'t\n    // enter via the ⋯ menu (which locks to one image), default the scope to\n    // \"Selected (N).\" Their selection IS the intent.\n    var hasSelection = !lockScope && isSelecting() && selectionCount() > 0;\n    state.reframe = {\n      productId: o.productId,\n      imgs: o.imgs,\n      focusedIndex: focusedIndex,\n      lockScope: lockScope,\n      scope: lockScope ? 'one' : (hasSelection ? 'selected' : 'main'),  // 'one' | 'main' | 'all' | 'selected'\n      tight: localStorage.getItem(LS.reframeTight) || 'normal',\n      fill:  localStorage.getItem(LS.reframeFill)  || 'color',\n      color: localStorage.getItem(LS.reframeColor) || '#FFFFFF',\n      previewSeq: 0,   // bumps on every change so stale RPC responses don\\'t paint\n      previewUrl: null,\n    };\n    document.getElementById('reframeSheetTitle').textContent = 'Reframe & crop';\n    paintReframeSheet();\n    openSheet('reframeSheet');\n    schedulePreview(0); // first preview right away\n  }\n\n  function paintReframeSheet() {\n    var r = state.reframe; if (!r) return;\n    // Scope chips. Locked entry from ⋯ menu shows a single read-only chip\n    // for the image; otherwise the toggle between Main and All.\n    var scopeEl = document.getElementById('reframeScopeChips');\n    scopeEl.innerHTML = '';\n    if (r.lockScope) {\n      var only = document.createElement('span');\n      only.className = 'chip is-active';\n      only.textContent = 'This image (#' + (r.focusedIndex + 1) + (r.focusedIndex === 0 ? ' · main' : '') + ')';\n      scopeEl.appendChild(only);\n    } else {\n      scopeEl.appendChild(reframeChip('Main image (#1)', r.scope === 'main', function () { setScope('main'); }));\n      // v0.49.12: third option when a multi-selection exists. Shows the\n      // exact count so the user can sanity-check before tapping Apply.\n      if (isSelecting() && selectionCount() > 0) {\n        scopeEl.appendChild(reframeChip(\n          'Selected (' + selectionCount() + ')',\n          r.scope === 'selected',\n          function () { setScope('selected'); }\n        ));\n      }\n      scopeEl.appendChild(reframeChip('All ' + r.imgs.length + ' images', r.scope === 'all', function () { setScope('all'); }));\n    }\n    // Tightness\n    var tightEl = document.getElementById('reframeTightChips');\n    tightEl.innerHTML = '';\n    REFRAME_TIGHTNESS.forEach(function (opt) {\n      tightEl.appendChild(reframeChip(opt.label, r.tight === opt.key, function () { setTight(opt.key); }));\n    });\n    // Fill\n    var fillEl = document.getElementById('reframeFillChips');\n    fillEl.innerHTML = '';\n    REFRAME_FILLS.forEach(function (opt) {\n      fillEl.appendChild(reframeChip(opt.label, r.fill === opt.key, function () { setFill(opt.key); }));\n    });\n    // Colour row (only when Fill = solid colour). For Blur we hide it.\n    var colorRow = document.getElementById('reframeColorRow');\n    if (r.fill === 'color') {\n      colorRow.style.display = '';\n      var colorEl = document.getElementById('reframeColorChips');\n      colorEl.innerHTML = '';\n      var matched = false;\n      REFRAME_COLORS.forEach(function (opt) {\n        var active = r.color.toUpperCase() === opt.key.toUpperCase();\n        if (active) matched = true;\n        var chip = reframeChip('', active, function () { setColor(opt.key); });\n        // Build chip contents: swatch dot + label.\n        var dot = document.createElement('span'); dot.className = 'reframe-color-swatch'; dot.style.background = opt.key;\n        chip.prepend(dot);\n        chip.appendChild(document.createTextNode(opt.label));\n        colorEl.appendChild(chip);\n      });\n      // \"Custom…\" chip — opens the hidden native colour picker. Active when\n      // the current colour isn\\'t one of the presets.\n      var customChip = reframeChip('Custom…', !matched, function () {\n        var pk = document.getElementById('reframeColorPicker');\n        pk.value = r.color;\n        // Trigger native picker via .click(); iOS Safari supports this.\n        pk.click();\n      });\n      if (!matched) {\n        var dot2 = document.createElement('span'); dot2.className = 'reframe-color-swatch'; dot2.style.background = r.color;\n        customChip.prepend(dot2);\n      }\n      colorEl.appendChild(customChip);\n    } else {\n      colorRow.style.display = 'none';\n    }\n    // Preview label — which image we\\'re showing.\n    var srcIdx = previewSourceIndex();\n    var srcImg = r.imgs[srcIdx];\n    var labelTxt = 'Previewing #' + (srcIdx + 1) + (srcIdx === 0 ? ' · main' : '');\n    if (!r.lockScope && r.scope === 'all') labelTxt += ' — same settings apply to all ' + r.imgs.length + ' images';\n    document.getElementById('reframePreviewLabel').textContent = labelTxt;\n    // Apply button label.\n    var n = applyFilepaths().length;\n    document.getElementById('reframeApplyBtn').textContent =\n      'Apply to ' + n + ' image' + (n === 1 ? '' : 's');\n  }\n\n  function reframeChip(label, isActive, onClick) {\n    var b = document.createElement('button');\n    b.type = 'button';\n    b.className = 'chip' + (isActive ? ' is-active' : '');\n    if (label) b.textContent = label;\n    b.addEventListener('click', function (ev) { ev.preventDefault(); onClick(); });\n    return b;\n  }\n\n  function setScope(s) { state.reframe.scope = s; paintReframeSheet(); schedulePreview(200); }\n  function setTight(k) {\n    state.reframe.tight = k;\n    try { localStorage.setItem(LS.reframeTight, k); } catch (_) {}\n    paintReframeSheet(); schedulePreview(200);\n  }\n  function setFill(k) {\n    state.reframe.fill = k;\n    try { localStorage.setItem(LS.reframeFill, k); } catch (_) {}\n    paintReframeSheet(); schedulePreview(200);\n  }\n  function setColor(hex) {\n    state.reframe.color = hex.toUpperCase();\n    try { localStorage.setItem(LS.reframeColor, state.reframe.color); } catch (_) {}\n    paintReframeSheet(); schedulePreview(200);\n  }\n  document.getElementById('reframeColorPicker').addEventListener('input', function () {\n    setColor(this.value || '#FFFFFF');\n  });\n\n  // Which image to preview — when scope is \"one\" or \"main\" we preview that\n  // image; when \"all\" we preview the main (#0) as the representative one.\n  function previewSourceIndex() {\n    var r = state.reframe; if (!r) return 0;\n    if (r.scope === 'one') return r.focusedIndex;\n    if (r.scope === 'main') return 0;\n    // v0.49.12: \"selected\" → preview the FIRST selected image in gallery\n    // order. Looks better than picking an arbitrary one from the Set.\n    if (r.scope === 'selected') {\n      for (var i = 0; i < r.imgs.length; i++) {\n        if (state.selected.has(r.imgs[i].filepath)) return i;\n      }\n    }\n    return 0; // all → still preview the main image\n  }\n  function applyFilepaths() {\n    var r = state.reframe; if (!r) return [];\n    if (r.scope === 'one')  return [r.imgs[r.focusedIndex].filepath];\n    if (r.scope === 'main') return [r.imgs[0].filepath];\n    if (r.scope === 'selected') {\n      // Filter to selection ∩ this product\\'s current images so a stale\n      // entry (selection from before a delete, say) doesn\\'t throw a 4xx.\n      return r.imgs.map(function (x) { return x.filepath; })\n                   .filter(function (fp) { return state.selected.has(fp); });\n    }\n    return r.imgs.map(function (x) { return x.filepath; });\n  }\n\n  // Debounced preview. Every control change bumps state.reframe.previewSeq;\n  // the response is only painted if its seq matches the latest one, so the\n  // user dragging through chip taps doesn\\'t end up with the second-to-last\n  // preview painting on top of the last.\n  var previewTimer = null;\n  function schedulePreview(delayMs) {\n    var r = state.reframe; if (!r) return;\n    r.previewSeq = (r.previewSeq || 0) + 1;\n    var seq = r.previewSeq;\n    if (previewTimer) clearTimeout(previewTimer);\n    document.getElementById('reframeBusy').hidden = false;\n    previewTimer = setTimeout(function () { runPreview(seq); }, Math.max(0, delayMs || 350));\n  }\n  function runPreview(seq) {\n    var r = state.reframe; if (!r) return;\n    var srcIdx = previewSourceIndex();\n    var src = r.imgs[srcIdx];\n    var opt = reframeOpt(REFRAME_TIGHTNESS, r.tight);\n    rpc('images:reframePreview', {\n      productId: r.productId, filepath: src.filepath,\n      scale: opt.scale,\n      offsetX: 0, offsetY: 0,\n      fillMode: r.fill,\n      fillColor: r.color,\n      autoCrop: true, trimThreshold: 12,\n    })\n      .then(function (res) {\n        if (!state.reframe || state.reframe.previewSeq !== seq) return; // stale\n        var url = envelopeToBlobUrl(res && res.bytes, 'image/png');\n        if (!url) return;\n        var imgEl = document.getElementById('reframePreviewImg');\n        // Revoke the previous URL so we don\\'t leak blobs across redraws.\n        if (state.reframe.previewUrl) { try { URL.revokeObjectURL(state.reframe.previewUrl); } catch (_) {} }\n        state.reframe.previewUrl = url;\n        imgEl.src = url; imgEl.hidden = false;\n        document.getElementById('reframeBusy').hidden = true;\n      })\n      .catch(function (e) {\n        if (!state.reframe || state.reframe.previewSeq !== seq) return;\n        document.getElementById('reframeBusy').hidden = false;\n        document.getElementById('reframeBusy').textContent = 'Preview failed: ' + (e.message || 'unknown');\n      });\n  }\n  function closeReframeSheet() {\n    closeSheet('reframeSheet');\n    if (state.reframe && state.reframe.previewUrl) {\n      try { URL.revokeObjectURL(state.reframe.previewUrl); } catch (_) {}\n    }\n    state.reframe = null;\n  }\n  function applyReframeSheet() {\n    var r = state.reframe; if (!r) return;\n    var opt = reframeOpt(REFRAME_TIGHTNESS, r.tight);\n    var paths = applyFilepaths();\n    closeReframeSheet();\n    runReframeCrop(r.productId, paths, {\n      scale: opt.scale, fillMode: r.fill, fillColor: r.color, trimThreshold: 12,\n    });\n  }\n  document.getElementById('reframeCancelBtn').addEventListener('click', closeReframeSheet);\n  document.getElementById('reframeApplyBtn').addEventListener('click', applyReframeSheet);\n  document.getElementById('reframeSheetClose').addEventListener('click', closeReframeSheet);\n  document.getElementById('reframeSheet').addEventListener('click', function (e) { if (e.target === this) closeReframeSheet(); });\n\n  /* ── v0.49.13: Enhance sheet ──────────────────────────────────\n     Auto white-balance + auto-levels + saturation/brightness boost. Same\n     UX skeleton as Reframe (preview + scope + Apply) with a single control\n     row: Strength. Maps to three presets so users don\\'t need to pick\n     numbers. Live preview via `images:autoEnhancePreview`. */\n  var ENHANCE_PRESETS = [\n    { key: 'subtle', label: 'Subtle', saturation: 1.03, brightness: 1.00 },\n    { key: 'normal', label: 'Normal', saturation: 1.08, brightness: 1.00 }, // matches desktop default\n    { key: 'punchy', label: 'Punchy', saturation: 1.18, brightness: 1.05 },\n  ];\n  function enhancePreset(key) {\n    for (var i = 0; i < ENHANCE_PRESETS.length; i++) if (ENHANCE_PRESETS[i].key === key) return ENHANCE_PRESETS[i];\n    return ENHANCE_PRESETS[1]; // Normal\n  }\n  function openEnhanceSheet(o) {\n    if (!o || !o.imgs || !o.imgs.length) return;\n    var focusedIndex = (o.focusedIndex != null) ? o.focusedIndex : 0;\n    var lockScope = !!o.lockScope;\n    var hasSelection = !lockScope && isSelecting() && selectionCount() > 0;\n    state.enhance = {\n      productId: o.productId,\n      imgs: o.imgs,\n      focusedIndex: focusedIndex,\n      lockScope: lockScope,\n      scope: lockScope ? 'one' : (hasSelection ? 'selected' : 'main'),\n      strength: localStorage.getItem(LS.enhanceStrength) || 'normal',\n      previewSeq: 0,\n      previewUrl: null,\n    };\n    paintEnhanceSheet();\n    openSheet('enhanceSheet');\n    scheduleEnhancePreview(0);\n  }\n  function paintEnhanceSheet() {\n    var e = state.enhance; if (!e) return;\n    // Scope chips — same shape as reframe.\n    var scopeEl = document.getElementById('enhanceScopeChips');\n    scopeEl.innerHTML = '';\n    if (e.lockScope) {\n      var only = document.createElement('span');\n      only.className = 'chip is-active';\n      only.textContent = 'This image (#' + (e.focusedIndex + 1) + (e.focusedIndex === 0 ? ' · main' : '') + ')';\n      scopeEl.appendChild(only);\n    } else {\n      scopeEl.appendChild(reframeChip('Main image (#1)', e.scope === 'main', function () { setEnhanceScope('main'); }));\n      if (isSelecting() && selectionCount() > 0) {\n        scopeEl.appendChild(reframeChip(\n          'Selected (' + selectionCount() + ')',\n          e.scope === 'selected',\n          function () { setEnhanceScope('selected'); }\n        ));\n      }\n      scopeEl.appendChild(reframeChip('All ' + e.imgs.length + ' images', e.scope === 'all', function () { setEnhanceScope('all'); }));\n    }\n    // Strength chips.\n    var strEl = document.getElementById('enhanceStrengthChips');\n    strEl.innerHTML = '';\n    ENHANCE_PRESETS.forEach(function (p) {\n      strEl.appendChild(reframeChip(p.label, e.strength === p.key, function () { setEnhanceStrength(p.key); }));\n    });\n    // Preview label.\n    var srcIdx = enhancePreviewSourceIndex();\n    var labelTxt = 'Previewing #' + (srcIdx + 1) + (srcIdx === 0 ? ' · main' : '');\n    if (!e.lockScope && e.scope === 'all')      labelTxt += ' — same settings apply to all ' + e.imgs.length + ' images';\n    else if (!e.lockScope && e.scope === 'selected') labelTxt += ' — same settings apply to all ' + selectionCount() + ' selected';\n    document.getElementById('enhancePreviewLabel').textContent = labelTxt;\n    // Apply button label.\n    var n = enhanceApplyFilepaths().length;\n    document.getElementById('enhanceApplyBtn').textContent =\n      'Apply to ' + n + ' image' + (n === 1 ? '' : 's');\n  }\n  function setEnhanceScope(s) { state.enhance.scope = s; paintEnhanceSheet(); scheduleEnhancePreview(200); }\n  function setEnhanceStrength(k) {\n    state.enhance.strength = k;\n    try { localStorage.setItem(LS.enhanceStrength, k); } catch (_) {}\n    paintEnhanceSheet(); scheduleEnhancePreview(200);\n  }\n  function enhancePreviewSourceIndex() {\n    var e = state.enhance; if (!e) return 0;\n    if (e.scope === 'one') return e.focusedIndex;\n    if (e.scope === 'main') return 0;\n    if (e.scope === 'selected') {\n      for (var i = 0; i < e.imgs.length; i++) {\n        if (state.selected.has(e.imgs[i].filepath)) return i;\n      }\n    }\n    return 0;\n  }\n  function enhanceApplyFilepaths() {\n    var e = state.enhance; if (!e) return [];\n    if (e.scope === 'one')  return [e.imgs[e.focusedIndex].filepath];\n    if (e.scope === 'main') return [e.imgs[0].filepath];\n    if (e.scope === 'selected') {\n      return e.imgs.map(function (x) { return x.filepath; })\n                   .filter(function (fp) { return state.selected.has(fp); });\n    }\n    return e.imgs.map(function (x) { return x.filepath; });\n  }\n  var enhancePreviewTimer = null;\n  function scheduleEnhancePreview(delayMs) {\n    var e = state.enhance; if (!e) return;\n    e.previewSeq = (e.previewSeq || 0) + 1;\n    var seq = e.previewSeq;\n    if (enhancePreviewTimer) clearTimeout(enhancePreviewTimer);\n    document.getElementById('enhanceBusy').hidden = false;\n    enhancePreviewTimer = setTimeout(function () { runEnhancePreview(seq); }, Math.max(0, delayMs || 350));\n  }\n  function runEnhancePreview(seq) {\n    var e = state.enhance; if (!e) return;\n    var srcIdx = enhancePreviewSourceIndex();\n    var src = e.imgs[srcIdx];\n    var p = enhancePreset(e.strength);\n    rpc('images:autoEnhancePreview', {\n      productId: e.productId, filepath: src.filepath,\n      whiteBalance: true, autoLevels: true,\n      saturation: p.saturation, brightness: p.brightness,\n    })\n      .then(function (res) {\n        if (!state.enhance || state.enhance.previewSeq !== seq) return; // stale\n        var url = envelopeToBlobUrl(res && res.bytes, 'image/png');\n        if (!url) return;\n        var imgEl = document.getElementById('enhancePreviewImg');\n        if (state.enhance.previewUrl) { try { URL.revokeObjectURL(state.enhance.previewUrl); } catch (_) {} }\n        state.enhance.previewUrl = url;\n        imgEl.src = url; imgEl.hidden = false;\n        document.getElementById('enhanceBusy').hidden = true;\n      })\n      .catch(function (err) {\n        if (!state.enhance || state.enhance.previewSeq !== seq) return;\n        document.getElementById('enhanceBusy').hidden = false;\n        document.getElementById('enhanceBusy').textContent = 'Preview failed: ' + (err.message || 'unknown');\n      });\n  }\n  function closeEnhanceSheet() {\n    closeSheet('enhanceSheet');\n    if (state.enhance && state.enhance.previewUrl) {\n      try { URL.revokeObjectURL(state.enhance.previewUrl); } catch (_) {}\n    }\n    state.enhance = null;\n  }\n  function applyEnhanceSheet() {\n    var e = state.enhance; if (!e) return;\n    var preset = enhancePreset(e.strength);\n    var paths = enhanceApplyFilepaths();\n    var pid = e.productId;\n    closeEnhanceSheet();\n    runEnhance(pid, paths, { saturation: preset.saturation, brightness: preset.brightness });\n  }\n  function runEnhance(pid, filepaths, opts) {\n    opts = opts || {};\n    var btn = document.getElementById('enhanceBtn');\n    var n = filepaths.length;\n    btn.disabled = true; btn.textContent = 'Enhancing ' + n + '…';\n    rpc('images:autoEnhanceProducts', {\n      productIds: [pid],\n      filepaths: filepaths,\n      whiteBalance: true, autoLevels: true,\n      saturation: opts.saturation != null ? opts.saturation : 1.08,\n      brightness: opts.brightness != null ? opts.brightness : 1.00,\n    })\n      .then(function (res) {\n        var done = (res && res.images) || 0;\n        var failed = (res && res.failed) || 0;\n        // Same in-place overwrite as reframe — bust the blob cache so\n        // thumbs re-fetch the new bytes.\n        for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n        delete imgListCache[pid]; delete mainImgCache[pid];\n        renderGallery(pid);\n        toast(failed\n          ? ('Enhanced ' + done + ', ' + failed + ' failed')\n          : ('Enhanced ' + done + ' image' + (done === 1 ? '' : 's')));\n      })\n      .catch(function (e) { toast('Enhance failed: ' + e.message); })\n      .finally(function () { btn.disabled = false; btn.textContent = '✨ Enhance'; });\n  }\n  document.getElementById('enhanceBtn').addEventListener('click', function () {\n    if (!currentDetail) return;\n    var pid = currentDetail.id;\n    getImageList(pid).then(function (imgs) {\n      if (!imgs || !imgs.length) { toast('No images to enhance'); return; }\n      openEnhanceSheet({ productId: pid, imgs: imgs, focusedIndex: 0, lockScope: false });\n    });\n  });\n  document.getElementById('enhanceCancelBtn').addEventListener('click', closeEnhanceSheet);\n  document.getElementById('enhanceApplyBtn').addEventListener('click', applyEnhanceSheet);\n  document.getElementById('enhanceSheetClose').addEventListener('click', closeEnhanceSheet);\n  document.getElementById('enhanceSheet').addEventListener('click', function (e) { if (e.target === this) closeEnhanceSheet(); });\n\n  /* ── v0.49.14: Overlay sheet ──────────────────────────────────\n     Applies a saved overlay template to the product\\'s main image and\n     either appends the result as a new image, or replaces the main with\n     it (demoting the original to #2). Source is always main — matches\n     the desktop\\'s `templates:applyToProduct` semantics; no scope picker\n     because the operation always produces a derived image, not an edit. */\n  function openOverlaySheet(o) {\n    if (!o || !o.productId) return;\n    state.overlay = {\n      productId: o.productId,\n      templates: [],\n      templateId: localStorage.getItem(LS.overlayTemplateId) || null,\n      destKind:   localStorage.getItem(LS.overlayDestKind)   || 'append',\n      previewSeq: 0,\n      previewUrl: null,\n    };\n    paintOverlaySheet();           // paint with whatever\\'s in state\n    openSheet('overlaySheet');\n    // Fetch the catalog and re-paint. Each company\\'s templates are\n    // fetched fresh — they\\'re short lists and the user might have added\n    // new ones since the last open.\n    rpc('templates:list').then(function (rows) {\n      var arr = Array.isArray(rows) ? rows : [];\n      if (!state.overlay) return; // sheet was closed while fetching\n      state.overlay.templates = arr;\n      // If the saved templateId no longer exists in the catalog, drop it\n      // so we don\\'t leave the chip stuck on a phantom selection.\n      if (state.overlay.templateId && !arr.some(function (t) { return t.id === state.overlay.templateId; })) {\n        state.overlay.templateId = null;\n      }\n      paintOverlaySheet();\n      if (state.overlay.templateId) scheduleOverlayPreview(0);\n    }).catch(function (e) {\n      if (!state.overlay) return;\n      document.getElementById('overlayBusy').hidden = false;\n      document.getElementById('overlayBusy').textContent = 'Failed to load templates: ' + (e.message || 'unknown');\n    });\n  }\n  function paintOverlaySheet() {\n    var o = state.overlay; if (!o) return;\n    // Template strip\n    var strip = document.getElementById('overlayTemplateStrip');\n    strip.innerHTML = '';\n    if (!o.templates || !o.templates.length) {\n      strip.innerHTML = '<div class=\"overlay-empty\">No templates yet. Create one in Overlay Studio on the desktop.</div>';\n    } else {\n      o.templates.forEach(function (t) {\n        var card = document.createElement('div');\n        card.className = 'overlay-template-card' + (t.id === o.templateId ? ' is-active' : '');\n        card.innerHTML = '<div class=\"name\">' + escapeHtml(t.name || '(no name)') + '</div>'\n                       + '<div class=\"meta\">' + (t.canvasWidth || '?') + ' × ' + (t.canvasHeight || '?') + '</div>';\n        card.addEventListener('click', function () { pickOverlayTemplate(t.id); });\n        strip.appendChild(card);\n      });\n    }\n    // Destination chips\n    var destEl = document.getElementById('overlayDestChips');\n    destEl.innerHTML = '';\n    destEl.appendChild(reframeChip('Append (new image)',  o.destKind === 'append',      function () { setOverlayDest('append'); }));\n    destEl.appendChild(reframeChip('Replace main',        o.destKind === 'replaceMain', function () { setOverlayDest('replaceMain'); }));\n    // Preview label\n    var t = o.templates && o.templates.length && o.templateId\n      ? o.templates.find(function (x) { return x.id === o.templateId; })\n      : null;\n    document.getElementById('overlayPreviewLabel').textContent =\n      t ? ('Applying “' + (t.name || '') + '” to the main image') : 'Pick a template above';\n    // Apply button\n    var btn = document.getElementById('overlayApplyBtn');\n    btn.disabled = !o.templateId;\n    btn.textContent = o.destKind === 'replaceMain' ? 'Apply (replace main)' : 'Apply (append)';\n  }\n  function pickOverlayTemplate(id) {\n    if (!state.overlay) return;\n    state.overlay.templateId = id;\n    try { localStorage.setItem(LS.overlayTemplateId, id); } catch (_) {}\n    paintOverlaySheet();\n    scheduleOverlayPreview(150);\n  }\n  function setOverlayDest(kind) {\n    if (!state.overlay) return;\n    state.overlay.destKind = kind;\n    try { localStorage.setItem(LS.overlayDestKind, kind); } catch (_) {}\n    paintOverlaySheet();\n    // Destination doesn\\'t affect the preview pixels, so no preview rerun.\n  }\n  var overlayPreviewTimer = null;\n  function scheduleOverlayPreview(delayMs) {\n    var o = state.overlay; if (!o || !o.templateId) return;\n    o.previewSeq = (o.previewSeq || 0) + 1;\n    var seq = o.previewSeq;\n    if (overlayPreviewTimer) clearTimeout(overlayPreviewTimer);\n    document.getElementById('overlayBusy').hidden = false;\n    document.getElementById('overlayBusy').textContent = 'Rendering preview…';\n    overlayPreviewTimer = setTimeout(function () { runOverlayPreview(seq); }, Math.max(0, delayMs || 250));\n  }\n  function runOverlayPreview(seq) {\n    var o = state.overlay; if (!o || !o.templateId) return;\n    rpc('templates:renderPreview', { templateId: o.templateId, productId: o.productId })\n      .then(function (res) {\n        if (!state.overlay || state.overlay.previewSeq !== seq) return;\n        var url = envelopeToBlobUrl(res && res.bytes, 'image/png');\n        if (!url) return;\n        var imgEl = document.getElementById('overlayPreviewImg');\n        if (state.overlay.previewUrl) { try { URL.revokeObjectURL(state.overlay.previewUrl); } catch (_) {} }\n        state.overlay.previewUrl = url;\n        imgEl.src = url; imgEl.hidden = false;\n        document.getElementById('overlayBusy').hidden = true;\n      })\n      .catch(function (e) {\n        if (!state.overlay || state.overlay.previewSeq !== seq) return;\n        document.getElementById('overlayBusy').hidden = false;\n        document.getElementById('overlayBusy').textContent = 'Preview failed: ' + (e.message || 'unknown');\n      });\n  }\n  function closeOverlaySheet() {\n    closeSheet('overlaySheet');\n    if (state.overlay && state.overlay.previewUrl) {\n      try { URL.revokeObjectURL(state.overlay.previewUrl); } catch (_) {}\n    }\n    state.overlay = null;\n  }\n  function applyOverlaySheet() {\n    var o = state.overlay; if (!o || !o.templateId) return;\n    var pid = o.productId, tid = o.templateId, dest = { kind: o.destKind };\n    closeOverlaySheet();\n    var btn = document.getElementById('overlayBtn');\n    btn.disabled = true; btn.textContent = 'Applying…';\n    rpc('templates:applyToProduct', { templateId: tid, productId: pid, destination: dest })\n      .then(function (res) {\n        // Append: new image at end of gallery. ReplaceMain: new image at #0,\n        // original demoted to #1. Either way bust the caches + re-render.\n        for (var k in blobCache) { try { URL.revokeObjectURL(blobCache[k]); } catch (e) {} delete blobCache[k]; }\n        delete imgListCache[pid]; delete mainImgCache[pid];\n        // Bump local imageCount so the count in the detail header is right\n        // without waiting for a fresh products:list.\n        if (currentDetail && currentDetail.id === pid) currentDetail.imageCount = (currentDetail.imageCount || 0) + 1;\n        var prod = state.products.find(function (x) { return x.id === pid; });\n        if (prod) prod.imageCount = (prod.imageCount || 0) + 1;\n        renderGallery(pid);\n        toast((res && res.skipped) ? 'Overlay matched an existing image (no duplicate added)' : 'Overlay applied');\n      })\n      .catch(function (e) { toast('Overlay failed: ' + e.message); })\n      .finally(function () { btn.disabled = false; btn.textContent = '◫ Overlay'; });\n  }\n  document.getElementById('overlayBtn').addEventListener('click', function () {\n    if (!currentDetail) return;\n    var pid = currentDetail.id;\n    getImageList(pid).then(function (imgs) {\n      if (!imgs || !imgs.length) { toast('Add a photo first — overlay needs a base image'); return; }\n      openOverlaySheet({ productId: pid });\n    });\n  });\n  document.getElementById('overlayCancelBtn').addEventListener('click', closeOverlaySheet);\n  document.getElementById('overlayApplyBtn').addEventListener('click', applyOverlaySheet);\n  document.getElementById('overlaySheetClose').addEventListener('click', closeOverlaySheet);\n  document.getElementById('overlaySheet').addEventListener('click', function (e) { if (e.target === this) closeOverlaySheet(); });\n\n  /* ── 360° spin (drag through a product's photos as frames) ──── */\n  var spinState = null; // { urls, idx, n, startX, startIdx, dragging }\n  function setSpinFrame(i) {\n    var s = spinState; if (!s) return;\n    s.idx = ((i % s.n) + s.n) % s.n;\n    document.getElementById('spinFrame').style.backgroundImage = 'url(\"' + s.urls[s.idx] + '\")';\n  }\n  function openSpin(productId) {\n    var btn = document.getElementById('spinBtn');\n    btn.disabled = true;\n    getImageList(productId).then(function (imgs) {\n      if (!imgs || imgs.length < 2) { toast('Add 2+ photos to spin'); return; }\n      var rels = imgs.map(function (im) { return (im.isProcessed && im.processedFilepath) ? im.processedFilepath : im.filepath; });\n      return Promise.all(rels.map(assetUrl)).then(function (urls) {\n        urls = urls.filter(Boolean);\n        if (urls.length < 2) { toast('Could not load frames'); return; }\n        spinState = { urls: urls, idx: 0, n: urls.length, startX: 0, startIdx: 0, dragging: false };\n        setSpinFrame(0);\n        document.getElementById('spin').classList.add('open');\n        document.body.style.overflow = 'hidden';\n      });\n    }).catch(function (e) { toast(e.message); }).finally(function () { btn.disabled = false; });\n  }\n  function closeSpin() {\n    document.getElementById('spin').classList.remove('open');\n    // Spin is opened from within the detail sheet, which also locks body\n    // scroll. Only release the lock if the detail sheet is now closed too —\n    // otherwise the page would scroll behind the still-open sheet.\n    document.body.style.overflow = document.getElementById('detail').classList.contains('open') ? 'hidden' : '';\n    spinState = null;\n  }\n  (function () {\n    var stage = document.getElementById('spinStage');\n    var PX = 26;\n    stage.addEventListener('pointerdown', function (e) {\n      if (!spinState) return;\n      spinState.dragging = true; spinState.startX = e.clientX; spinState.startIdx = spinState.idx;\n      try { stage.setPointerCapture(e.pointerId); } catch (_) {}\n    });\n    stage.addEventListener('pointermove', function (e) {\n      var s = spinState; if (!s || !s.dragging) return;\n      setSpinFrame(s.startIdx + Math.round(-(e.clientX - s.startX) / PX));\n    });\n    function end() { if (spinState) spinState.dragging = false; }\n    stage.addEventListener('pointerup', end);\n    stage.addEventListener('pointercancel', end);\n    document.getElementById('spinClose').addEventListener('click', closeSpin);\n    document.getElementById('spin').addEventListener('click', function (e) { if (e.target === this) closeSpin(); });\n    document.getElementById('spinBtn').addEventListener('click', function () { if (currentDetail) openSpin(currentDetail.id); });\n  })();\n\n  /* ──────────────────────────────────────────────────────────────\n     v0.49.5: image preview lightbox\n     ──────────────────────────────────────────────────────────────\n     Fullscreen viewer for a single product image. Opened by tapping a\n     gallery tile; prev/next via buttons or 1-finger swipe. iOS pinch-zoom\n     still works on the image (touch-action: pinch-zoom on the stage), and\n     long-press triggers the system \"Save Image\" sheet so users can save\n     to their camera roll without us shipping a save button. */\n\n  var previewState = null; // { images: [...], index: number }\n\n  function openImgPreview(imgs, startIndex) {\n    if (!imgs || !imgs.length) return;\n    var n = imgs.length;\n    var idx = Math.max(0, Math.min(startIndex || 0, n - 1));\n    previewState = { images: imgs, index: idx };\n    paintImgPreview();\n    document.getElementById('imgPreview').classList.add('open');\n    document.body.style.overflow = 'hidden';\n  }\n  function paintImgPreview() {\n    var s = previewState; if (!s) return;\n    var img = s.images[s.index];\n    var rel = (img.isProcessed && img.processedFilepath) ? img.processedFilepath : img.filepath;\n    var el = document.getElementById('imgPreviewImg');\n    el.src = ''; // clear while the new one loads (avoids a flash of the old)\n    assetUrl(rel).then(function (url) {\n      // Bail if state moved on (rapid prev/next swipes).\n      if (url && previewState && previewState.images[previewState.index] === img) {\n        el.src = url;\n        el.alt = img.filename || '';\n      }\n    });\n    document.getElementById('imgPreviewInfo').textContent =\n      '#' + (s.index + 1) + ' of ' + s.images.length + (s.index === 0 ? ' · main' : '');\n    document.getElementById('imgPreviewPrev').disabled = s.index <= 0;\n    document.getElementById('imgPreviewNext').disabled = s.index >= s.images.length - 1;\n  }\n  function previewPrev() {\n    if (!previewState || previewState.index <= 0) return;\n    previewState.index -= 1; paintImgPreview();\n  }\n  function previewNext() {\n    if (!previewState || previewState.index >= previewState.images.length - 1) return;\n    previewState.index += 1; paintImgPreview();\n  }\n  function closeImgPreview() {\n    document.getElementById('imgPreview').classList.remove('open');\n    // Restore scroll lock state — detail sheet (if open) needs it back.\n    document.body.style.overflow = document.getElementById('detail').classList.contains('open') ? 'hidden' : '';\n    previewState = null;\n    document.getElementById('imgPreviewImg').src = '';\n  }\n  document.getElementById('imgPreviewClose').addEventListener('click', closeImgPreview);\n  document.getElementById('imgPreviewPrev').addEventListener('click', previewPrev);\n  document.getElementById('imgPreviewNext').addEventListener('click', previewNext);\n  document.getElementById('imgPreview').addEventListener('click', function (e) {\n    // Backdrop tap (anything outside the image / nav buttons) closes.\n    if (e.target.id === 'imgPreview' || e.target.id === 'imgPreviewStage') closeImgPreview();\n  });\n\n  // 1-finger swipe on the stage → prev/next. Multi-touch (pinch) is left\n  // alone so iOS handles native zoom.\n  (function () {\n    var stage = document.getElementById('imgPreviewStage');\n    var sx = 0; var sy = 0; var dragging = false;\n    stage.addEventListener('touchstart', function (e) {\n      if (e.touches.length > 1) { dragging = false; return; }\n      dragging = true; sx = e.touches[0].clientX; sy = e.touches[0].clientY;\n    }, { passive: true });\n    stage.addEventListener('touchend', function (e) {\n      if (!dragging || !e.changedTouches.length) { dragging = false; return; }\n      dragging = false;\n      var dx = e.changedTouches[0].clientX - sx;\n      var dy = e.changedTouches[0].clientY - sy;\n      // Only treat as horizontal swipe if it's more horizontal than vertical.\n      if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy)) {\n        if (dx < 0) previewNext(); else previewPrev();\n      }\n    }, { passive: true });\n  })();\n\n  /* ──────────────────────────────────────────────────────────────\n     v0.49.5: keyboard-aware sheet sizing\n     ──────────────────────────────────────────────────────────────\n     iOS pops the on-screen keyboard ABOVE the layout viewport — the sheet's\n     vh-based max-height doesn't shrink, so the sheet's top edge floats\n     off-screen and the search input vanishes behind the keyboard. Watch\n     visualViewport and toggle the `is-keyboard` class on any open sheet so\n     CSS re-anchors it to the top with a visualViewport-sized max-height. */\n  function syncSheetsToViewport() {\n    var open = document.querySelectorAll('.sheet-overlay.open');\n    if (!open.length) return;\n    var visH = (window.visualViewport && window.visualViewport.height) || window.innerHeight;\n    // Heuristic: if the visual viewport is more than 120px short of the\n    // layout viewport, the keyboard is up. 120px is roughly the smallest\n    // possible iOS keyboard (a numeric keypad); the regular keyboard takes\n    // ~300px. Either way we want the sheet pinned to the top.\n    var keyboardUp = (window.innerHeight - visH) > 120;\n    open.forEach(function (s) {\n      s.classList.toggle('is-keyboard', keyboardUp);\n      if (keyboardUp) s.style.setProperty('--vvh', visH + 'px');\n      else s.style.removeProperty('--vvh');\n    });\n  }\n  if (window.visualViewport) {\n    window.visualViewport.addEventListener('resize', syncSheetsToViewport);\n    window.visualViewport.addEventListener('scroll', syncSheetsToViewport);\n  }\n  window.addEventListener('resize', syncSheetsToViewport);\n  document.getElementById('photoInput').addEventListener('change', function () {\n    handleAddPhotos(this.files);\n    this.value = ''; // reset so the same photo can be picked again\n  });\n\n  function closeDetail() {\n    document.getElementById('detail').classList.remove('open');\n    document.body.style.overflow = '';\n    stopAiPolling(); // v0.47.0 — no point polling once the sheet is closed.\n    if (isSelecting()) exitSelectMode(); // v0.49.12 — selection belongs to this product\\'s view.\n  }\n  document.getElementById('detailClose').addEventListener('click', closeDetail);\n  document.getElementById('detail').addEventListener('click', function (e) { if (e.target === this) closeDetail(); });\n\n  /* ── helpers ───────────────────────────────────────────────── */\n  function escapeHtml(s) {\n    return String(s == null ? '' : s).replace(/[&<>\"']/g, function (c) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c];\n    });\n  }\n  function fmtBytes(n) {\n    if (!n) return '';\n    if (n < 1024 * 1024) return Math.max(1, Math.round(n / 1024)) + ' KB';\n    var mb = n / (1024 * 1024); return (mb >= 10 ? Math.round(mb) : mb.toFixed(1)) + ' MB';\n  }\n\n  /* ── start ─────────────────────────────────────────────────── */\n  if (baseUrl && token) {\n    document.getElementById('connect').style.display = 'none';\n    document.getElementById('app').style.display = 'block';\n    boot();\n  } else {\n    showConnect('');\n  }\n})();\n</script>\n</body>\n</html>\n";
